window.TXB=window.TXB||{};TXB["alab/1Ki"]={"1:1":"وشاخ الملك داود وطعن في السن، فكانوا يدثرونه بالأغطية فلا يشعر بالدفء.","1:2":"فقال له عبيده: «ليلتمس سيدنا الملك فتاة عذراء تخدمك، وتعتني بك وتضطجع في حضنك، فتبعث فيك الدفء».","1:3":"فبحثوا له عن فتاة جميلة في أرجاء إسرائيل، فعثروا على أبيشج الشونمية فأحضروها إلى الملك.","1:4":"وكانت الفتاة بارعة الجمال، فصارت له حاضنة، تقوم على خدمته، ولكن الملك لم يعاشرها.","1:5":"وعظم أدونيا ابن حجيث نفسه قائلا: «أنا أملك»، وجهز لنفسه مركبات وفرسانا واستأجر خمسين رجلا يجرون أمام موكبه.","1:6":"ولم يغضبه أبوه قط بسؤاله: «لماذا فعلت هكذا؟» وكان أدونيا وسيم الطلعة، وقد أنجبته أمه بعد أبشالوم.","1:7":"وتداول الأمر مع يوآب بن صروية وأبياثار الكاهن فأعاناه،","1:8":"وأما صادوق الكاهن وبناياهو بن يهوياداع وناثان النبي وشمعي وريعي وسواهم من الأبطال من رجال داود فلم ينساقوا معه.","1:9":"وتوجه أدونيا إلى عين روجل حيث ذبح غنما وبقرا ومسمنات عند حجر الزاحفة، ودعا جميع إخوته أبناء الملك، وجميع رجال يهوذا من حاشية داود،","1:10":"ولكنه لم يدع ناثان النبي ولا بناياهو، ولا الرجال الأبطال ولا سليمان أخاه.","1:11":"فأقبل ناثان النبي إلى بثشبع أم سليمان قائلا: «ألم تعلمي أن أدونيا ابن حجيث قد ملك، وسيدنا داود لم يعرف بالأمر بعد؟","1:12":"فالآن تعالي أشير عليك بما ينقذك وينقذ ابنك سليمان.","1:13":"امضي وادخلي إلى الملك داود وقولي له: ألم تحلف ياسيدي الملك لجاريتك أن ابني سليمان يكون الملك من بعدي وهو يجلس على عرشي؟ فلماذا ملك أدونيا إذا؟»","1:14":"وفيما أنت تخاطبين الملك أدخل وراءك، وأؤيد كلامك.","1:15":"فمثلت بثشبع أمام الملك الشيخ في مخدعه، وكانت أبيشج الشونمية قائمة على خدمته.","1:16":"فأكبت بثشبع على وجهها وسجدت للملك، فسألها الملك: «مالك؟»","1:17":"فأجابته: «لقد حلفت لي بالرب إلهك ياسيدي قائلا: «إن سليمان ابني يصبح ملكا من بعدي ويجلس على عرشي»","1:18":"ولكن ها هو أدونيا قد ملك من غير علم منك ياسيدي الملك،","1:19":"وقد ذبح ثيرانا ومسمنات وغنما بوفرة، ودعا جميع أبناء الملك، وأبياثار الكاهن، ويوآب رئيس الجيش، ولكن لم يدع سليمان عبدك.","1:20":"إن جميع أعين شعب إسرائيل، ياسيدي الملك، تتجه نحوك في انتظار إعلانك من يخلف سيدي الملك على عرشه.","1:21":"وإلا حالما ينضم سيدي الملك إلى آبائه نعامل أنا وابني سليمان معاملة المذنبين».","1:22":"وفيما هي تخاطب الملك جاء ناثان النبي،","1:23":"فقيل للملك: «قد جاء ناثان النبي». فمثل في حضرة الملك وسجد له،","1:24":"وتساءل ناثان: «هل قلت ياسيدي الملك: إن أدونيا يملك من بعدي ويخلفني على عرشي؟","1:25":"لأنه قد مضى اليوم وذبح ثيرانا ومسمنات وغنما بوفرة، ودعا جميع أبناء الملك ورؤساء الجيش وأبياثار الكاهن، وها هم يحتفلون آكلين شاربين أمامه هاتفين: ليحي الملك أدونيا!","1:26":"وأما أنا وصادوق الكاهن وبناياهو بن يهوياداع وسليمان فلم يدعنا.","1:27":"فهل صدر هذا الأمر عن سيدي الملك من غير أن تطلع عبدك عمن يخلفك على عرشك؟»","1:28":"فأجاب الملك: «استدع لي بثشبع». فمثلت أمام الملك،","1:29":"فحلف الملك: «حي هو الرب الذي أنقذ نفسي من كل ضيق،","1:30":"كما أقسمت لك بالرب إله إسرائيل أن ابنك سليمان يملك بعدي ويخلفني على عرشي، هكذا أفعل هذا اليوم».","1:31":"فخرت بثشبع على وجهها إلى الأرض ساجدة للملك وقالت: «ليحي سيدي الملك داود إلى الأبد!»","1:32":"وقال الملك داود: استدع لي صادوق الكاهن وناثان النبي وبناياهو بن يهوياداع». فدخلوا إلى حضرة الملك","1:33":"فقال الملك لهم: «خذوا معكم رجال حاشية سيدكم، وأركبوا سليمان ابني على بغلتي الخاصة، وانطلقوا به إلى جيحون.","1:34":"وليمسحه هناك صادوق الكاهن وناثان النبي ملكا على إسرائيل، وانفخوا بالبوق هاتفين: «ليحي الملك سليمان».","1:35":"ثم اصعدوا وراءه حتى يأتي فيجلس على عرشي، فهو الذي اخترته ليخلفني على عرش إسرائيل ويهوذا».","1:36":"فقال بناياهو بن يهوياداع للملك: «آمين! ليكن هذا ما يعلنه الرب إله سيدي الملك!","1:37":"وكما كان الرب مع سيدي الملك ليكن مع سليمان، ويجعل عرشه أعظم من عرش سيدي الملك داود».","1:38":"ومضى صادوق الكاهن وناثان النبي وبناياهو بن يهوياداع وضباط حرس الملك، وأركبوا سليمان على بغلة الملك داود، وانطلقوا به إلى جيحون.","1:39":"فأخذ صادوق الكاهن قرن الدهن من الخيمة ومسح سليمان، ونفخوا بالبوق وهتف جميع الشعب: «ليحي الملك سليمان».","1:40":"وصعد جميع الشعب وراء سليمان وهم يعزفون على الناي هاتفين فرحا، حتى ارتجت الأرض من أصواتهم.","1:41":"وسمع أدونيا ومدعووه جميعا أصوات الهتاف بعد أن فرغوا من الأكل، وبلغ نفير البوق مسامع يوآب فتساءل: «ما معنى هذا الضجيج في المدينة؟»","1:42":"وفيما هو يتساءل جاء يوناثان بن أبياثار الكاهن، فقال أدونيا: «تعال، فأنت رجل كريم تحمل بشائر خير».","1:43":"فأجاب يوناثان أدونيا: «لا إن سيدنا الملك داود قد نصب سليمان ملكا،","1:44":"وبعث معه صادوق الكاهن وناثان النبي وبناياهو بن يهوياداع وضباط حرسه، فأركبوه على بغلة الملك،","1:45":"ومسحه صادوق الكاهن وناثان النبي ملكا في جيحون، ثم صعدوا من هناك فرحين هاتفين، حتى ملأ ضجيجهم المدينة. وهذا هو مصدر الصوت الذي سمعتموه.","1:46":"وقد جلس سليمان على كرسي المملكة».","1:47":"وتوافد رجال الملك داود لتهنئته قائلين: «ليجعل إلهك اسم سليمان أكثر شهرة من اسمك، وعرشه أعظم من عرشك». فسجد الملك على سريره","1:48":"قائلا: «تبارك الرب إله إسرائيل الذي أنعم علي بمن يخلفني على عرشي وأنا مازلت على قيد الحياة».","1:49":"فاعترت الرعدة جميع مدعوي أدونيا، فقاموا وتفرقوا كل في سبيله.","1:50":"وملأ الخوف أدونيا من سليمان، فانطلق مسرعا وتمسك بقرون المذبح.","1:51":"فقيل لسليمان: «ها هو أدونيا قد ملأه الخوف منك، وقد لجأ إلى المذبح يتمسك بقرونه ويقول: ليحلف لي اليوم سليمان أنه لا يقتل عبده بالسيف».","1:52":"فقال سليمان: «إن أثبت صدق ولائه فإن شعرة واحدة من رأسه لن تسقط إلى الأرض، ولكن إن أضمر الخيانة والشر فإنه حتما يموت».","1:53":"فأرسل الملك سليمان من أحضره من عند المذبح، فأتى وسجد للملك سليمان، فقال له سليمان: «اذهب إلى بيتك».","2:1":"وعندما أحس داود بدنو أجله، أوصى سليمان ابنه قائلا:","2:2":"«أنا ماض إلى مصير كل أهل الأرض، فتشجع وكن رجلا.","2:3":"احفظ شرائع إلهك. سر في سبله وأطع فرائضه ووصاياه وأحكامه وشهاداته، كما هي مدونة في شريعة موسى، ليحالفك النجاح في كل ما تفعل وحيثما تتوجه،","2:4":"فيحقق الرب وعوده التي وعدني بها قائلا: إذا حفظ بنوك طريقهم وسلكوا أمامي بإخلاص من كل قلوبهم وأنفسهم، فإنه لن ينقطع لك رجل عن اعتلاء عرش إسرائيل.","2:5":"أنت تعلم ما جناه علي يوآب ابن صروية حين قتل قائدي جيوش إسرائيل: أبنير بن نير وعماسا بن يثر، فسفك دما في وقت السلم، وكأنه في خضم حرب، فلطخ بذلك الدم حزام حقويه ونعلي رجليه.","2:6":"فاقض بما تمليه عليك حكمتك، ولا تدع رأسه الأشيب يموت في سلام.","2:7":"واصنع معروفا لبني برزلاي الجلعادي، فيكونوا بين الآكلين الدائمين على مائدتك، لأنهم وقفوا إلى جانبي عند هروبي من وجه أبشالوم أخيك.","2:8":"وهناك أيضا شمعي بن جيرا البنياميني من بحوريم، فقد صب علي أشد اللعنات يوم انطلقت إلى محنايم، ولكنه انحدر للقائي عند نهر الأردن مستغفرا، فحلفت له بالرب أنني لن أميته بالسيف،","2:9":"أما أنت فلا تبرره من ذنبه، وأنت رجل حكيم، فانظر ما تعاقبه به. أحدر شيبته إلى القبر ملطخة بالدم».","2:10":"ثم مات داود ودفن في أورشليم.","2:11":"وكانت فترة حكم داود أربعين سنة، ملك سبع سنين في حبرون وثلاثا وثلاثين سنة في أورشليم.","2:12":"وأصبح سليمان ملكا على إسرائيل خلفا لوالده داود، وتثبتت دعائم مملكته.","2:13":"وجاء أدونيا بن حجيث إلى بثشبع أم سليمان فسألته: «أجئت مسالما؟» فأجابها: «مسالما»،","2:14":"وأضاف: «ولدي ما أطلبه منك». فقالت: «تكلم» فقال:","2:15":"«أنت تعلمين أن الملك كان من حقي، وأن جميع الإسرائيليين قد التفوا حولي لأكون ملكا عليهم، ولكن تحولت الأمور، وصار الملك لأخي بمقتضى أمر الرب.","2:16":"ولي الآن مطلب واحد، فلا تخيبي أملي فيه،","2:17":"اطلبي من سليمان الملك أن يزوجني من أبيشج الشونمية فهو لا يرد لك سولا».","2:18":"فأجابته بثشبع: «أنا أخاطب الملك في الأمر نيابة عنك».","2:19":"ودخلت بثشبع إلى سليمان لترفع إليه مطلب أدونيا، فهب الملك لاستقبالها وسجد لها، ثم جلس على العرش، وأعد لها مقعدا ملكيا آخر فجلست عن يمينه،","2:20":"وقالت: «جئت أطلب منك أمرا واحدا بسيطا، فلا تردني خائبة». فأجابها: «اسألي ياأمي، لأني لن أخيب لك رجاء».","2:21":"فقالت: «زوج أدونيا أخاك من أبيشج الشونمية».","2:22":"فأجابها الملك: «لماذا تطلبين أبيشج الشونمية فقط لأدونيا؟ اطلبي له الملك أيضا، فهو أخي الأكبر، فيصبح الملك له ولأبياثار الكاهن ويوآب ابن صروية».","2:23":"وحلف سليمان الملك بالرب قائلا: «ليعاقبني الرب أشد عقاب ويزد إن لم يدفع أدونيا حياته ثمنا لهذا المطلب.","2:24":"حي هو الرب الذي ثبتني وأجلسني على عرش داود أبي وأعطاني ملكا كما وعد. اليوم يموت أدونيا».","2:25":"وأرسل الملك سليمان بناياهو بن يهوياداع فقتل أدونيا.","2:26":"وقال الملك لأبياثار الكاهن: «انطلق إلى حقولك في عناثوث وامكث هناك، فأنت اليوم مستوجب الموت، ولكنني لن أقتلك، لأنك حملت تابوت سيدي الرب أمام داود أبي ولأنك قاسيت من كل ما قاسى منه أيضا».","2:27":"وطرد سليمان أبياثار من وظيفة الكهنوت، ليتم كلام الرب الذي حكم به على نسل عالي في شيلوه.","2:28":"فبلغ الخبر يوآب الذي كان قد تآمر مع أدونيا وليس مع أبشالوم، فهرب إلى خيمة الرب وتشبث بقرون المذبح،","2:29":"فقيل للملك سليمان إن يوآب قد لجأ إلى خيمة الرب، وها هو مقيم إلى جوار المذبح، فأمر سليمان بناياهو بن يهوياداع أن يذهب ويقتله.","2:30":"فدخل بناياهو إلى خيمة الرب وقال ليوآب: «الملك يأمرك بالخروج» فأجاب: «لا. لن أخرج بل أموت هنا» فأبلغ بناياهو الملك جواب يوآب","2:31":"فقال له الملك: «افعل مثلما قال، واقتله وادفنه وأزل عني وعن بيت أبي ذنب الدماء الزكية التي سفكها يوآب،","2:32":"فيحمله الرب وحده وزر إثمه، لأنه اغتال بالسيف رجلين بريئين، هما أفضل منه، من غير علم داود أبي، وهما أبنير بن نير رئيس جيش إسرائيل، وعماسا بن يثر رئيس جيش يهوذا،","2:33":"فيرتد دمهما على رأس يوآب ورأس نسله إلى الأبد، ويملأ سلام الرب داود ونسله وبيته وعرشه إلى مدى الدهر».","2:34":"فانطلق بناياهو بن يهوياداع وقتل يوآب. ودفن في جوار بيته في الصحراء.","2:35":"وعين الملك بناياهو بن يهوياداع مكانه قائدا للجيش، وأقام صادوق الكاهن مكان أبياثار.","2:36":"ثم استدعى الملك شمعي بن جيرا وقال له: «ابن لك بيتا في أورشليم وأقم هناك، وإياك أن تغادر المدينة.","2:37":"واعلم أنك يوم تتخطى وادي قدرون فإنك حتما تموت ويكون دمك على رأسك».","2:38":"فأجاب شمعي الملك: «حسنا، فإن عبدك ينفذ كل ما يأمر به سيدي الملك». فأقام شمعي في أورشليم أياما كثيرة.","2:39":"وفي ختام ثلاث سنوات هرب عبدان لشمعي إلى أخيش بن معكة ملك جت، فقيل لشمعي هوذا عبداك في جت.","2:40":"فقام وأسرج حماره وارتحل إلى جت إلى أخيش ليبحث عن عبديه. ولما وجدهما عاد بهما من جت.","2:41":"فبلغ سليمان أن شمعي قد غادر أورشليم إلى جت ثم عاد إليها،","2:42":"فاستدعاه وقال له: «أما استحلفتك بالرب وأشهدت عليك أنك يوم تغادر المدينة إلى أي مكان آخر حتما تموت. فأجبتني: حسنا، وسمعا وطاعة.","2:43":"فلماذا نقضت يمين الرب ونكثت ما أوصيتك به؟»","2:44":"ثم قال الملك له: «أنت تدرك في قرارة نفسك كل الشر الذي ارتكبته في حق أبي، فليعاقبك الرب بما جنته يداك.","2:45":"أما الملك فلينعم عليه الرب ببركاته، وليكن عرش داود راسخا أمام الرب إلى الأبد».","2:46":"وأمر الملك بناياهو بن يهوياداع أن يخرج بشمعي ويقتله، وهكذا ثبت الملك لسليمان.","3:1":"وتزوج سليمان ابنة فرعون ملك مصر، وأحضرها إلى مدينة داود ريثما يتم إكمال بناء قصره وبيت الرب والسور المحيط بأورشليم.","3:2":"وكان الشعب آنئذ يقدمون ذبائح على المرتفعات، لأن بيت الرب لم يكن قد بني بعد.","3:3":"وأحب سليمان الرب وسار في فرائض داود أبيه، إلا أنه واظب على تقديم ذبائح وإيقاد بخور على المرتفعات.","3:4":"ومضى سليمان إلى جبعون، المرتفعة العظمى، وأصعد هناك ألف محرقة على ذلك المذبح.","3:5":"وفي جبعون تراءى الرب له ليلا في حلم، وقال له: «اطلب ماذا أعطيك؟»","3:6":"فأجاب: «لقد صنعت إلى عبدك داود أبي رحمة واسعة لأنه سلك أمامك بأمانة وصلاح واستقامة قلب، فلم تحرمه من الرحمة العظيمة، ورزقته ابنا يخلفه على عرشه في هذا اليوم.","3:7":"والآن أيها الرب إلهي، لقد جعلت عبدك ملكا خلفا لداود أبي، وأنا ما برحت فتى صغيرا غير متمرس بشؤون الحكم،","3:8":"وعبدك يتولى حكم شعبك الذي اخترته، وهو شعب أعظم من أن يعد أو يحصى لكثرته.","3:9":"فهب عبدك قلبا فهيما لأقضي بين شعبك، وأميز بين الخير والشر، لأنه من يستطيع أن يحكم شعبك العظيم هذا؟»","3:10":"فسر الرب بطلب سليمان هذا.","3:11":"وقال له: «لأنك قد طلبت هذا الأمر، ولم تطلب حياة طويلة، ولا غنى، ولا انتقاما من أعدائك، بل سألت حكمة لتسوس شؤون الحكم،","3:12":"فإنني سألبي طلبك، فأهبك قلبا حكيما مميزا، فلا يضاهيك أحد من قبل ولا من بعد.","3:13":"وقد أنعمت عليك أيضا بما لم تسأله، من غنى ومجد، حتى لا يكون لك نظير بين الملوك في أيامك.","3:14":"فإن سلكت في طريقي وأطعت فرائضي ووصاياي، كما سلك أبوك، فإني أطيل أيامك».","3:15":"وعندما استيقظ سليمان من نومه أدرك أن ذلك كان حلما، فعاد إلى أورشليم ووقف أمام تابوت عهد الرب وقرب محرقات وذبائح سلام، وأقام وليمة لكل رجاله.","3:16":"بعد ذلك حضرت امرأتان عاهرتان إلى الملك ليقضي بينهما،","3:17":"فقالت إحداهما: «استمع ياسيدي، إنني وهذه المرأة مقيمتان في بيت واحد ورزقت بطفل،","3:18":"ورزقت هي بطفل أيضا بعدي بثلاثة أيام، وكنا معا، لا يقيم بيننا غريب في البيت. كنا وحدنا فقط في البيت.","3:19":"فمات طفل هذه المرأة عندما انقلبت عليه في أثناء نومها.","3:20":"فنهضت في منتصف الليل وأنا مستغرقة في النوم، وأخذت طفلي من جانبي وأضجعته في حضنها، وأضجعت ابنها الميت في حضني.","3:21":"فلما هممت بإرضاع ابني في الصباح وجدته ميتا، وحين تأملت فيه في ضوء النهار تبينت أنه ليس طفلي الذي أنجبته».","3:22":"وشرعت المرأة الأخرى تقاطعها قائلة: «كلا. إن ابني هو الحي، وابنك هو الميت». فترد عليها الأخرى: «بل ابنك هو الميت وابني هو الحي». وهكذا اشتد الجدل أمام الملك،","3:23":"فقال الملك: «كل منكما تدعي أن الابن الحي هو ابنها وأن الابن الميت هو ابن الأخرى.","3:24":"لذلك ايتوني بسيف». فأحضروا للملك سيفا.","3:25":"فقال الملك: «اشطروا الطفل الحي إلى شطرين، وأعطوا كلا منهما شطرا».","3:26":"فالتهبت مشاعر الأم الحقيقية وقالت للملك: «أصغ ياسيدي، أعطها الطفل ولا تميتوه». أما المرأة الأخرى فكانت تقول: «لن يكون لك ولا لي: اشطروه».","3:27":"عندئد قال الملك: «أعطوا الطفل للمرأة التي أرادت له الحياة، فهي أمه».","3:28":"ولما سرى نبأ هذا الحكم الذي صدر عن الملك بين شعب إسرائيل، امتلأوا توقيرا له، لأنهم رأوا فيه حكمة الله لإجراء العدل.","4:1":"وملك سليمان على كل أرجاء إسرائيل.","4:2":"وهذه أسماء كبار معاونيه: عزرياهو بن صادوق الكاهن،","4:3":"وأليحورف وأخيا ابنا شيشا كاتبا البلاط، ويهوشافاط بن أخيلود المسؤول عن السجلات،","4:4":"وبناياهو بن يهوياداع قائد الجيش، وصادوق وأبياثار كاهنان،","4:5":"وعزرياهو بن ناثان مسؤول عن وكلاء المناطق، وزابود بن ناثان كاهن ونديم الملك،","4:6":"وأخيشار مدير شؤون القصر، وأدونيرام بن عبدا مسؤول عن الأشغال الشاقة.","4:7":"وعين سليمان اثني عشر وكيلا موزعين على أسباط إسرائيل، عهد إلى كل واحد منهم بإمداد القصر وأهله بالمؤن شهرا من كل سنة.","4:8":"وهذه هي أسماؤهم: ابن حور في جبل أفرايم.","4:9":"ابن دقر في ماقص وشعلبيم وبيت شمس وأيلون بيت حانان.","4:10":"ابن حسد في أربوت، وكان مسؤولا عن سوكوه وسائر أرض حافر أيضا.","4:11":"ابن أبيناداب، زوج طافة ابنة سليمان، في كل مرتفعات دور.","4:12":"بعنا بن أخيلود في تعنك ومجدو وكل بيت شان المجاورة لصرتان أسفل يزرعيل، فضلا عن كل الأراضي الواقعة ما بين بيت شان وآبل محولة حتى يقمعام.","4:13":"ابن جابر في راموت جلعاد، بما في ذلك قرى يائير بن منسى في جلعاد، وإقليم أرجوب في باشان، وهي ستون مدينة ذات أسوار وبوابات لها أرتاج نحاسية.","4:14":"أخيناداب بن عدو في محنايم.","4:15":"أخيمعص في نفتالي، وهو أيضا تزوج من باسمة ابنة سليمان.","4:16":"بعنا بن حوشاي في أشير وبعلوت.","4:17":"يهوشافاط بن فاروح في يساكر.","4:18":"شمعي بن أيلا في بنيامين.","4:19":"جابر بن أوري في أرض جلعاد التي كانت لسيحون ملك الأموريين وعوج ملك باشان، وكان يشرف على هؤلاء الوكلاء مراقب واحد عام.","4:20":"وكان عدد يهوذا وإسرائيل كرمل البحر في الكثرة لا يحصى، وكانوا يأكلون ويشربون ويتمتعون بالسعادة.","4:21":"وامتد سلطان سليمان على جميع الممالك الواقعة ما بين نهر الفرات إلى أرض الفلسطينيين وحتى تخوم مصر. فكانت هذه الممالك تقدم له الجزية وتخضع له كل أيام حياته.","4:22":"وكانت متطلبات القصر اليومية من الطعام ثلاثين كرسميذ (نحو سبعة آلاف ومئتي لتر)، وستين كر دقيق،","4:23":"وعشرة ثيران مسمنة، وعشرين ثورا من المراعي، ومئة خروف، فضلا عن الأيائل والغزلان واليحامير والإوز المسمن،","4:24":"لأن سلطانه كان ممتدا على كل الأراضي الواقعة غربي نهر الفرات من تفسح إلى غزة وعلى ملوكها، فكان السلام يحيط به من كل جانب.","4:25":"وتمتع إسرائيل ويهوذا بالأمن طوال حياة سليمان، فكان كل واحد يستمتع بالجلوس تحت ظلال كرمته وتينته من دان إلى بئر سبع","4:26":"وكان لسليمان أربعون ألف مذود لخيل مركباته، واثنا عشر ألف فارس.","4:27":"وكان وكلاء المناطق، كل في شهره، يمدون الملك سليمان وكل من يأكل على مائدته بالمؤونة، فلم يفتقروا إلى شيء.","4:28":"وكذلك جلبوا الشعير والتبن لخيل المركبات وسواها من الجياد إلى المواضع المعينة لكل وكيل.","4:29":"ووهب الله سليمان حكمة وفهما فائقين، ورحابة صدر غير متناهية.","4:30":"وتفوقت حكمة سليمان على جميع أبناء المشرق وكل حكمة المصريين.","4:31":"فكان أكثر حكمة من جميع الناس مثل إيثان الأزراحي وهيمان وكلكول ودردع أبناء ماحول. وذاع صيته بين جميع الأمم المجاورة.","4:32":"ونطق بثلاثة آلاف مثل، وبلغت أناشيده ألفا وخمس قصائد.","4:33":"ووصف الحياة النباتية بما في ذلك أشجار الأرز في لبنان، والزوفا النابت في الحائط، كما وصف البهائم والطير والزواحف والسمك.","4:34":"فأقبل الناس من جميع الأمم ليستمعوا إلى حكمة سليمان، موفدين من قبل ملوك الأرض الذين بلغتهم أخبار حكمته.","5:1":"وأرسل حيرام ملك صور وفدا إلى سليمان بعد أن سمع أنه اعتلى العرش خلفا لأبيه، وكان حيرام صديقا محبا لداود.","5:2":"فكتب سليمان رسالة إلى حيرام قائلا:","5:3":"«أنت تعلم أن أبي داود لم يستطع أن يبني بيتا لاسم الرب إلهه من جراء الحروب التي خاضها، حتى أظفره الرب بأعدائه وأخضعهم له.","5:4":"أما الآن وقد أراحني الرب من كل جانب، فليس من ثائر أو حادثة شر.","5:5":"وها أنا قد نويت أن أبني بيتا لاسم الرب إلهي، كما قال الرب لداود أبي: إن ابنك الذي يخلفك على عرشك هو يبني بيتا لاسمي العظيم.","5:6":"فأرجو أن تأمر رجالك أن يقطعوا لي أرزا من لبنان، وسيعمل رجالي جنبا إلى جنب مع رجالك، وأقوم أنا بدفع أجرة رجالك بموجب ما تراه، لأنك تعلم أنه ليس بين قومي من يمهر في قطع الأخشاب مثل الصيدونيين».","5:7":"فلما سمع حيرام كلام سليمان، غمرته البهجة وقال: «مبارك اليوم الرب الذي رزق داود ابنا حكيما ليملك على هذا الشعب الغفير».","5:8":"وبعث حيرام إلى سليمان برسالة قائلا: «قد اطلعت على رسالتك وسأعمل على تلبية رغبتك بشأن خشب الأرز وخشب السرو.","5:9":"سيقوم رجالي بنقل الخشب من جبل لبنان إلى البحر، ويربطون قطع الخشب إلى بعضها في حزم ضخمة، يعومها رجالي ويوجهونها إلى الموضع الذي تعينه، فيسلمونها لرجالك، وعليك لقاء ذلك، أن تمون قصري الملكي بما يحتاج إليه من طعام».","5:10":"فكان حيرام يوفر لسليمان ما يطلبه من خشب الأرز وخشب سرو،","5:11":"ويقدم سليمان لحيرام كل سنة لقاء ذلك، عشرين ألف كر حنطة (نحو أربعة آلاف وثماني مئة طن) طعاما لقصره، وعشرين ألف كر زيت نقي (نحو أربعة آلاف وثماني مئة لتر).","5:12":"ومنح الرب سليمان حكمة كما وعده، وعقد سليمان مع حيرام معاهدة سلام وصداقة.","5:13":"وسخر الملك سليمان ثلاثين ألف رجل من أرجاء إسرائيل،","5:14":"فكان يرسل منهم عشرة آلاف إلى لبنان لمدة شهر واحد مناوبة، فيقضون شهرا في لبنان وشهرين في بيوتهم. وكان أدونيرام المشرف على تنظيم عملية التسخير.","5:15":"وفضلا عن هؤلاء، كان لسليمان سبعون ألفا من حمالي الخشب وثمانون ألفا من قاطعي الحجارة في الجبل،","5:16":"ماعدا ثلاثة آلاف وثلاث مئة من المشرفين على هؤلاء العمال.","5:17":"وبناء على أمر الملك قام العمال بقلع حجارة كبيرة، هذبوها فصارت مربعة، لاستخدامها في أساس بناء الهيكل.","5:18":"فنحتها بناؤو سليمان بمساعدة بنائي حيرام وأهل جبيل، وهيأوا الأخشاب والحجارة لتشييد الهيكل.","6:1":"وعندما بدأ سليمان في بناء هيكل الرب في الشهر الثاني، شهر زيو (آيار ; مايو) من السنة الرابعة لتوليه عرش إسرائيل، كان قد انقضى على خروج بني إسرائيل من ديار مصر أربع مئة وثمانون عاما.","6:2":"وكان طول الهيكل الذي شيده سليمان للرب ستين ذراعا (نحو ثلاثين مترا) وعرضه عشرين ذراعا (نحو عشرة أمتار) وارتفاعه ثلاثين ذراعا (نحو خمسة عشرة مترا)","6:3":"وكانت هناك شرفة أمام الهيكل طولها عشرون ذراعا (نحو عشرة أمتار) وعرضها عشر أذرع (نحو خمسة أمتار)","6:4":"وصنع للهيكل نوافذ مسقوفة مشبكة ضيقة.","6:5":"وشيد على جوانب جدران القاعة الرئيسية والمحراب بناء ذا طوابق ثلاثة، محيطا بالهيكل جعله حجرات إضافية.","6:6":"وكان عرض الطبقة الأولى خمس أذرع (نحو مترين ونصف المتر)، وعرض الطبقة الثانية ست أذرع (نحو ثلاثة أمتار)، وعرض الطبقة الثالثة سبع أذرع (نحو ثلاثة أمتار ونصف المتر). وكانت الحجرات متصلة بجدران الهيكل بعوارض مرتكزة على كتل خشبية مثبتة خارج الجدران، وليس في باطن الجدران نفسها.","6:7":"وتم بناء الهيكل بحجارة صحيحة، اقتلعها العمال ونحتوها في مقالعها، فلم يسمع في الهيكل عند بنائه صوت منحت أو معول أو أي أداة حديدية.","6:8":"وكان مدخل الطابق الأسفل يقود إلى الجانب الأيمن من الهيكل، ومنه يصعدون بدرج يفضي إلى الطابقين الثاني والثالث.","6:9":"وبعد أن أكمل سليمان بناء الهيكل كسا سقفه بعوارض وألواح من خشب الأرز.","6:10":"وكان ارتفاع الحجرات الملحقة بالهيكل خمس أذرع (نحو مترين ونصف المتر)، وقد ثبتها بالهيكل بعوارض من خشب الأرز.","6:11":"وأوحى الرب إلى سليمان بشأن الهيكل قائلا:","6:12":"«أما ما يتعلق بهذا الهيكل الذي شيدته، إن سلكت في فرائضي وطبقت أحكامي وأطعت وصاياي، ومارستها فإنني أحقق وعودي التي وعدت بها داود أباك","6:13":"وأقيم وسط شعبي إسرائيل ولا أتخلى عنه».","6:14":"وهكذا شيد سليمان الهيكل وأكمله،","6:15":"وكسيت جدران الهيكل من الداخل، من الأرض إلى السقف بعوارض من خشب الأرز، وغطيت أرضيته بخشب السرو،","6:16":"واقتطع عشرين ذراعا (نحو عشرة أمتار) من مؤخرة الهيكل بنى فيها المحراب، أي قدس الأقداس بعد أن بنى جدرانا داخلية من الأرض إلى الحيطان بعوارض من خشب الأرز.","6:17":"وامتد باقي الهيكل أمام قدس الأقداس على طول أربعين ذراعا (نحو عشرين مترا).","6:18":"ونقشت على ألواح خشب الأرز التي غطت الجدران الداخلية أشكال يقطين، وبراعم زهور متفتحة. وكان البناء الداخلي مصنوعا كله من خشب الأرز فلم يظهر فيه حجر.","6:19":"وأعد سليمان محرابا في وسط الهيكل من داخل ليضع فيه تابوت عهد الرب.","6:20":"كان طوله عشرين ذراعا (نحو عشرة أمتار)، وعرضه عشرين ذراعا، وارتفاعه عشرين ذراعا. وغشاه بذهب نقي كما غشى المذبح بخشب الأرز.","6:21":"وبعد ذلك غشى سليمان الهيكل كله من داخل بذهب نقي. وصنع سلاسل ذهبية حجز بها مدخل المحراب المغشى بالذهب النقي.","6:22":"فكان الهيكل بكامله مغشى من الداخل بالذهب النقي، بما فيه مذبح المحراب.","6:23":"وأقام في المحراب كروبين مصنوعين من خشب الزيتون، علو الواحد منهما عشر أذرع (نحو خمسة أمتار).","6:24":"وطول جناحي الكروب الواحد، من الطرف الواحد إلى الطرف الآخر، عشر أذرع (نحو خمسة أمتار)","6:25":"وكذلك كان طول جناحي الكروب الثاني عشر أذرع (نحو خمسة أمتار)، لأنهما كانا متماثلين في القياس والشكل.","6:26":"وكان علو كل كروب عشر أذرع (نحو خمسة أمتار).","6:27":"وأقام الكروبين في وسط قدس الأقداس، بحيث يمتد طرفا جناحيهما الخارجيين من الحائط إلى الحائط، ويتلامس طرفا جناحيهما الداخليين في منتصف المحراب،","6:28":"وغشى سليمان الكروبين بالذهب.","6:29":"ونقشت على جميع الجدران المحيطة بالهيكل من الداخل والخارج رسوم كروبيم ونخيل وبراعم زهور.","6:30":"وغشى أرض الهيكل كله، بقسميه الداخلي والخارجي، بذهب.","6:31":"وكان للمحراب باب من مصراعين مصنوعين من خشب الزيتون، لهما عتبة وقائمتان على شكل مخمس.","6:32":"ونقش على المصراعين رسوم كروبيم ونخيل وبراعم زهور، وغشاهما بذهب، كما رصع الكروبيم والنخيل بذهب.","6:33":"وصنع لمدخل الهيكل قوائم مربعة من خشب الزيتون،","6:34":"ومصراعين من خشب السرو، لكل مصراع دفتان تنطويان على بعضهما.","6:35":"ونحت نقوش كروبيم ونخيل وبراعم زهور وغشاها بذهب مطروق.","6:36":"وكان جدار الساحة الداخلية مبنيا من ثلاث طبقات من الحجارة المنحوتة، وطبقة من عوارض الأرز المشذبة.","6:37":"وكان إرساء أساس بيت الرب في شهر زيو (أيار ; مايو) من السنة الرابعة لحكم سليمان.","6:38":"وفي شهر بول (تشرين الثاني ; نوفمبر) من العام الحادي عشر لملك سليمان، اكتمل بناء الهيكل بكل تفاصيله، وهكذا استغرق تشييده سبع سنوات.","7:1":"وبنى سليمان قصره في ثلاث عشرة سنة،","7:2":"وشيد أيضا قصرا عاما دعاه قصر غابة لبنان. وكان طوله مئة ذراع (نحو خمسين مترا) وعرضه خمسين ذراعا (نحو خمسة وعشرين مترا) وارتفاعه ثلاثين ذراعا (نحو خمسة عشر مترا)، ويقوم على أربعة صفوف من أعمدة مصنوعة من خشب الأرز، ترتكز عليها عوارض خشبية منسقة من خشب الأرز.","7:3":"وامتد سقف من خشب الأرز فوق هذه العوارض المنسقة البالغة خمسا وأربعين عارضة، قائمة على الأعمدة، وقد نسقت في صفوف ثلاثة، يتألف كل صف منها من خمس عشرة عارضة.","7:4":"وتتكون السقوف من ثلاث طبقات، لها نوافذ متقابلة في كل طبقة.","7:5":"وكان لكل المداخل والنوافذ إطارات مربعة الشكل، كما تقابلت كل نافذة مع نافذة أخرى، منسقة في ثلاثة صفوف.","7:6":"وكانت هناك قاعة أخرى اسمها «بهو الأعمدة» طولها خمسون ذراعا (نحو خمسة وعشرين مترا) وعرضها ثلاثون ذراعا (نحو خمسة عشر مترا) كما بنى أمامها شرفة تقوم على أعمدة مسقوفة.","7:7":"وكذلك شيد «قاعة العرش» أو «بهو القضاء» وغشاها بألواح من خشب الأرز من الأرض إلى السقف.","7:8":"أما بيته الذي كان يقيم فيه فكان خلف «قاعة العرش» مماثلا لها في فن البناء كما شيد قصرا مماثلا لزوجته ابنة فرعون.","7:9":"وقد شيدت هذه جميعا من حجارة ضخمة رفيعة المستوى، قطعت وشذبت وجوهها الداخلية والخارجية بمنشار وفق المقاييس المطلوبة، واستخدمت من الأساس إلى الإفريز ومن خارج إلى الدار الكبيرة.","7:10":"وكانت أساساتها من حجارة ضخمة رفيعة المستوى يتراوح حجمها ما بين ثماني إلى عشر أذرع (نحو أربعة إلى خمسة أمتار مكعبة).","7:11":"أما حجارة جدران البناء فقد قطعت بحسب مقاييس معينة، وكسيت بألواح من خشب الأرز.","7:12":"وتكونت جدران بهو القضاء من ثلاثة صفوف من الحجارة المنحوتة وصف من عوارض خشب الأرز، مماثلا بذلك رواق بيت الرب الداخلي وبهو القصر.","7:13":"واستدعى الملك سليمان رجلا من صور يدعى حيرام.","7:14":"كان ابنا لأرملة من سبط نفتالي، أما أبوه المتوفى فكان من صور يعمل نحاسا، وقد برع حيرام في مهنته وأتقنها، فانخرط في خدمة سليمان وأنجز الأعمال التي عهد بها إليه.","7:15":"وسبك حيرام عمودين من نحاس، طول العمود الواحد ثماني عشرة ذراعا (نحو تسعة أمتار) ومحيطه اثنتا عشرة ذراعا (نحو ستة أمتار)، وكانا أجوفين، سمك كل منهما نحو أربع أصابع.","7:16":"وصنع تاجين من النحاس المصبوب ليضعهما على رأسي عمودي النحاس. طول التاج الواحد خمس أذرع (نحو مترين ونصف المتر)،","7:17":"وزين كل تاج من التاجين الموضوعين على رأسي العمودين بسبع نوافذ من شباك مصنوعة من ضفائر النحاس.","7:18":"وسبك صفين من الرمان حول محيط العمودين على نوافذ الشبكتين،","7:19":"لتغطية التاجين اللذان على رأسي العمودين اللذين في الشرفة فقد كانا على شكل زهرة السوسن، وطول كل منهما أربع أذرع (نحو مترين)،","7:20":"وكان على كل من التاجين القائمين على العمودين، وفوق القمة المستديرة الشبيهة بالطاقة والتالية للشبكة مئتا رمانة، في صفوف حول محيط كل تاج.","7:21":"ونصب العمودين في شرفة الهيكل الخارجية، أحدهما إلى اليمين ودعاه ياكين، والآخر إلى الشمال ودعاه بوعز.","7:22":"وكان التاجان على شكل زهرة السوسن. وهكذا اكتمل صنع العمودين.","7:23":"وصنع حيرام بركة من نحاس وجعلها مستديرة، يبلغ طول قطرها من الحافة إلى الحافة عشر أذرع (نحو خمسة أمتار) وارتفاعها خمس أذرع (نحو مترين ونصف المتر)، وطول محيطها ثلاثين ذراعا (نحو خمسة عشر مترا)","7:24":"وسبك تحت استدارة محيط حافتها صفين من القثاء، عشر قثاءات لكل ذراع (نحو نصف المتر) وقد سبكت كلها، مع الحافة حين تم سبك البركة.","7:25":"وكانت البركة ترتكز على اثني عشر ثورا تتجه رؤوس ثلاثة منها نحو الشمال، وثلاثة منها نحو الغرب، وثلاثة منها نحو الجنوب، والثلاثة الأخيرة نحو الشرق. أما أعجازها جميعا فكانت متجهة نحو الداخل، ونصبت البركة عليها.","7:26":"وبلغ سمك جدار البركة شبرا، وصنعت حافتها على شكل كأس زهر السوسن، وهي تسع ألفي بث (نحو أحد عشر ألفا وخمس مئة جالون من الماء).","7:27":"وصنع حيرام أيضا عشر قواعد متحركة من نحاس، طول كل منها وعرضها أربع أذرع (نحو مترين)، وارتفاعها ثلاث أذرع (نحو متر ونصف).","7:28":"وهذه هي كيفية صنعها: كان لها أتراس مثبتة في وسط أطر،","7:29":"وطرق على الأتراس التي في وسط الأطر وعلى الأطر، أسودا وثيرانا وكروبيم. كما تدلت قلائد زهور من فوق الأسود والثيران ومن تحتها.","7:30":"وكان لكل قاعدة أربع بكرات نحاسية ذات محاور نحاسية، ولكل واحدة منها أكتاف لزواياها الأربع. وهذه الأكتاف مسبوكة تحت المرحضة بجوار كل قلادة.","7:31":"أما فمها فهو داخل إكليل، ويبلغ ارتفاعه ذراعا (نحو نصف المتر)، وهو مستدير مماثل للقاعدة، يبلغ عمقه ذراعا ونصف ذراع (نحو ثلاثة أرباع المتر)، وقد نقشت عليه نقوش. أما أتراسها فمربعة الشكل وليست مستديرة.","7:32":"وتقع البكرات تحت الأتراس، في حين أثبتت محاورها في القاعدة. وكان قطر البكرة ذراعا ونصف ذراع (نحو ثلاثة أرباع المتر).","7:33":"وصنعت البكرات على مثال عجلات المركبات. أما محاورها وأطرها وقضبانها وقبوبها فقد كانت كلها مسبوكة.","7:34":"وكان لكل قاعدة أكتاف أربع، هي جزء من القاعدة، قائمة على زواياها الأربع.","7:35":"وأعلى القاعدة مقبب مستدير يبلغ عمقه نصف ذراع (نحو ربع المتر)، وقد سبكت دعائمه وأتراسه مع القاعدة.","7:36":"وتم نقش كروبيم وأسود ونخيل، مع قلائد زهور، على جوانب الدعائم والأتراس، وفي كل مكان يتسع للنقش.","7:37":"هكذا صنع حيرام القواعد العشر، فكانت كلها متماثلة في السبك والقياس والشكل.","7:38":"وصنع حيرام أيضا عشرة مراحض من نحاس تسع كل مرحضة أربعين بثا (نحو مئتين وثلاثين جالونا من الماء)، قطر كل منها أربع أذرع (نحو مترين). فكان لكل قاعدة من العشر القواعد مرحضة.","7:39":"وأقام خمس قواعد على جانب الهيكل الأيمن، وخمسا على جانب الهيكل الأيسر، أما البركة فكانت في الركن الجنوبي الشرقي من الهيكل.","7:40":"وانتهى حيرام من صنع المراحض والرفوش والمناضح التي عهد بها إليه الملك سليمان لأجل بيت الرب،","7:41":"وكذلك من العمودين وكأسي التاجين القائمين على رأسي العمودين، والشبكتين لتغطية كأسي التاجين اللذين على رأسي العمودين،","7:42":"والأربع مئة رمانة المنقوشة في صفين حول الشبكتين اللتين تغطيان كأسي التاجين القائمين على العمودين،","7:43":"والقواعد العشر والمراحض العشر المثبتة على القواعد.","7:44":"والبركة المرتكزة على الاثني عشر ثورا،","7:45":"والقدور والرفوش والمناضح. وقد صنع حيرام من النحاس المصقول، جميع هذه الآنية التي عهد إليه بها الملك سليمان لهيكل الرب.","7:46":"وقد أمر الملك بسبكها في غور الأردن، في أرض الخزف، بين سكوت وصرتان.","7:47":"ولم يحاول سليمان وزن جميع هذه الآنية لفرط كثرتها، حتى لم يتم التحقق من وزن النحاس.","7:48":"وصنع سليمان جميع أواني هيكل الرب من ذهب، وكذلك المائدة التي يوضع عليها خبز الوجوه.","7:49":"كما صنعت المنائر التي وزعت أمام المحراب، خمسا إلى اليمين وخمسا إلى اليسار، من ذهب نقي، وأيضا الأزهار والسرج والملاقط كلها صنعت من ذهب.","7:50":"وصنعت الطسوس والمقصات والمناضح والمراحض والمجامر من ذهب نقي، كما صنعت مفصلات مصاريع قدس الأقداس وأبواب الهيكل من ذهب.","7:51":"وهكذا اكتمل العمل كله الذي قام به الملك سليمان لتشييد هيكل الرب، وأخذ سليمان مدخرات أبيه داود، من فضة وذهب وأوان، التي كرسها لهيكل الرب، ووضعها في خزائن الهيكل.","8:1":"حينئذ جمع سليمان جميع رؤساء بني إسرائيل وكل رؤساء الأسباط والعشائر في أورشليم، لنقل تابوت عهد الرب من صهيون مدينة داود إلى الهيكل.","8:2":"فتوافد جميع رجال إسرائيل إلى الملك سليمان في عيد المظال الواقع في شهر أيثانيم (تشرين الأول ; أكتوبر).","8:3":"فاحتشد كل شيوخ إسرائيل، وحمل الكهنة التابوت،","8:4":"ونقل الكهنة واللاويون تابوت الرب مع خيمة الاجتماع وسائر الأواني المقدسة التي في الخيمة.","8:5":"وكان الملك سليمان وكل جماعة إسرائيل الملتفين حوله أمام التابوت يذبحون ما لا يحصى ولا يعد من الغنم والبقر.","8:6":"وأدخل الكهنة تابوت عهد الرب إلى مكانه في محراب الهيكل، في قدس الأقداس، تحت جناحي الكروبين","8:7":"اللذين كانا باسطين أجنحتهما فوق مقر التابوت، مظللين التابوت وعصيه.","8:8":"وسحبوا أطراف العصي، فبدت رؤوسها من قدس الأقداس أمام المحراب، ولم يسبق أن شوهدت خارجة من حلقاتها، وهي ما برحت هناك إلى هذا اليوم.","8:9":"ولم يكن في التابوت سوى لوحي الحجر اللذين وضعهما موسى في حوريب حين عاهد الرب أبناء إسرائيل بعد خروجهم من ديار مصر.","8:10":"وما إن خرج الكهنة من قدس الأقداس حتى ملأ السحاب هيكل الرب،","8:11":"فلم يستطع الكهنة القيام بالخدمة من جراء السحاب، لأن مجد الرب ملأ الهيكل.","8:12":"عندئذ هتف سليمان: «قال الرب إنه يسكن في الضباب،","8:13":"ولكني قد بنيت لك هيكلا رائعا، مقرا لسكناك إلى الأبد».","8:14":"وفيما كانت كل جماعة إسرائيل واقفة هناك، التفت الملك نحوهم وباركهم جميعا،","8:15":"قائلا: «تبارك الرب إله إسرائيل الذي حقق اليوم وعده الذي قطعه لأبي داود قائلا:","8:16":"منذ أن أخرجت شعبي إسرائيل من مصر لم أختر مدينة من مدن أسباط إسرائيل ليبنى لي فيها هيكل، لكني اخترت داود قائدا لشعبي.","8:17":"وقد نوى داود أبي أن يشيد هيكلا للرب إله إسرائيل.","8:18":"فقال الرب لداود أبي: لقد أحسنت إذ نويت في قلبك أن تبني لي هيكلا،","8:19":"إلا أنك أنت لن تبني هذا الهيكل، بل ابنك الخارج من صلبك هو يشيده لاسمي».","8:20":"وأوفى الرب بما وعد به، فخلفت أنا داود أبي على عرش إسرائيل، كما تكلم الرب، وأقمت هذا الهيكل للرب إله إسرائيل،","8:21":"وهيأت فيه مكانا للتابوت الذي يضم عهد الرب الذي قطعه مع آبائنا عندما أخرجهم من ديار مصر».","8:22":"وانتصب سليمان أمام مذبح الرب، في مواجهة كل جماعة إسرائيل، وبسط يديه إلى السماء،","8:23":"وقال: «أيها الرب إله إسرائيل، ليس نظير لك في السماء من فوق ولا على الأرض من أسفل. أنت يامن تحافظ على عهد الرحمة مع عبيدك السائرين أمامك من كل قلوبهم.","8:24":"اليوم حققت وعدك لأبي داود","8:25":"فالآن احفظ لأبي داود ما وعدته به، إنه إذا حذا أولاده حذوه، وساروا في طريقك، فسيجلس دوما واحد منهم على عرش إسرائيل.","8:26":"والآن ياإله إسرائيل حقق وعودك التي تعهدت بها لأبي داود.","8:27":"ولكن هل يسكن الله حقا على الأرض؟ إن كانت السماوات، بل السماوات العلى لا تسعك فكيف يتسع لك هذا الهيكل الذي بنيت؟","8:28":"فاصغ لابتهال عبدك وإلى تضرعه أيها الرب إلهي، واستمع إلى صوت الدعاء والصلاة التي يرفعها عبدك أمامك اليوم،","8:29":"حتى لا تغفل عيناك عن هذا الهيكل ليلا ونهارا، هذا الموضع الذي قلت إن اسمك يكون فيه، فتسمع الصلاة التي يتضرع بها عبدك في هذا الموضع.","8:30":"فاستمع إلى ابتهال عبدك وشعبك إسرائيل الذين يصلون في هذا المكان. استمع من السماء مقر سكناك، ومتى سمعت فاغفر.","8:31":"وإن أخطأ أحد إلى صاحبه، وأوجب عليه اليمين ليحلفه، وحضر ليحلف أمام مذبحك في هذا الهيكل،","8:32":"فاستمع أنت من السماء، واعمل، واقض بين عبيدك، إذ تدين المذنب وتجعل شره يقع على رأسه، وتنصف البار وتعلن براءته.","8:33":"إذا انهزم شعبك أمام عدوهم من جراء خطيئتهم، ثم تابوا معترفين باسمك، وصلوا متضرعين إليك في هذا الهيكل،","8:34":"فاستجب أنت من السماء واصفح عن خطيئة شعبك إسرائيل، وأرجعهم إلى الأرض التي وهبتها لآبائهم.","8:35":"إذا أغلقت أبواب السماء وانحبس المطر لأن الشعب أخطأ إليك، ثم صلوا في هذا الهيكل معترفين باسمك، وتابوا عن خطيئتهم لأنك أنزلت بهم البلاء،","8:36":"فاستجب أنت من السماء، واصفح عن خطيئة عبيدك وشعبك إسرائيل، وعلمهم سبيل العيش باستقامة، وأمطر غيثا على الأرض التي وهبتها ميراثا لشعبك..","8:37":"وإن أصابت الأرض مجاعة، أو تفشى فيها وبأ، أو اعترتها آفات زراعية، أو جفاف، أو غزاها الجراد والجندب، أو إذا حاصر الشعب عدو في أية مدينة من مدنه، أو حلت به كارثة أو مرض،","8:38":"فحين يصلي أو يتضرع أي واحد من كل شعبك إسرائيل، بعد أن يدرك ما ارتكبه من معصية، ويبسط يديه نحو هذا الهيكل،","8:39":"فاستجب أنت من السماء مقر سكناك، واصفح واعمل، واجز كل إنسان بمقتضى طرقه، لأنك تعرف قلبه، فأنت وحدك المطلع على خفايا قلوب الناس،","8:40":"لكي يتقوك كل الأيام التي يحيون فيها على وجه الأرض التي وهبتها لآبائنا.","8:41":"أما الغريب الذي لا ينتمي إلى شعبك إسرائيل، والذي يقبل من أرض بعيدة من أجل اسمك،","8:42":"لأن الغرباء يسمعون باسمك العظيم، وبما أجرته يدك القوية وذراعك المقتدرة، فيحضرون ويصلون في هذا الهيكل،","8:43":"فاستجب أنت من السماء مقر سكناك، وافعل كل ما يناشدك به الغريب، فيدعى باسمك بين كل أمم الأرض، فيخافوك كما يخافك شعبك إسرائيل، ويدركوا أن اسمك قد دعي على هذا الهيكل الذي بنيته.","8:44":"وإذا خرج شعبك لمحاربة عدو، في أي مكان ترسلهم إليه، وصلوا إلى الرب متوجهين نحو المدينة التي اخترتها والهيكل الذي بنيته لاسمك،","8:45":"فاستجب من السماء صلاتهم وتضرعهم، وانصر قضيتهم.","8:46":"وإذا أخطأوا إليك، إذ ليس إنسان لا يأثم، وغضبت عليهم وأسلمتهم للعدو فسباهم آسروهم إلى ديار العدو، بعيدة أو قريبة.","8:47":"فإن تابوا في أرض سبيهم ورجعوا متضرعين إليك قائلين: قد أخطأنا وانحرفنا وأذنبنا،","8:48":"وتابوا حقا من كل قلوبهم ونفوسهم وهم أسرى في ديار أعدائهم، متوجهين نحو أرضهم التي وهبتها لآبائهم، نحو المدينة التي اخترتها والهيكل الذي شيدته لاسمك،","8:49":"فاستجب صلاتهم وتضرعهم من السماء مقر سكناك، وانصر قضيتهم،","8:50":"واصفح عن خطايا شعبك وعن جميع ذنوبهم التي ارتكبوها في حقك، واجعل آسريهم يبدون نحوهم رحمة،","8:51":"لأنهم شعبك وميراثك الذين أخرجتهم من مصر، من وسط أتون صهر الحديد.","8:52":"لتكن عيناك مفتوحتين ملتفتتين نحو تضرع عبدك وابتهال شعبك إسرائيل، فتصغي إليهم كلما استغاثوا بك،","8:53":"لأنك أنت أفرزتهم لك ميراثا بين جميع شعوب الأرض، كما تكلمت على لسان عبدك موسى عندما أخرجت آباءنا من مصر ياسيدي الرب».","8:54":"وعندما انتهى سليمان من الصلاة إلى الرب والتضرع إليه، نهض من أمام المذبح حيث كان جاثيا على ركبتيه وباسطا يديه نحو السماء.","8:55":"ووقف وبارك الشعب كله بصوت عال قائلا:","8:56":"«تبارك الرب الذي منح راحة لشعبه إسرائيل بمقتضى وعده، ولم يخلف كلمة واحدة من وعوده الصالحة التي نطق بها على لسان عبده موسى.","8:57":"ليكن الرب إلهنا معنا كما كان مع آبائنا، فلا يتركنا ولا ينبذنا،","8:58":"بل ليجتذب قلوبنا إليه لنسلك في سبله ونطيع وصاياه وفرائضه وأحكامه التي أمر بها آباءنا،","8:59":"ولتكن كلماتي التي تضرعت بها ماثلة دائما أمام الرب ليل نهار ليسعف عبده في قضاء شؤونه، ويعين شعبه إسرائيل في قضاء أمور حياتهم يوما بعد يوم،","8:60":"فتعلم كل أمم الأرض أن الرب هو الله وليس أحد سواه.","8:61":"فليكن قلبكم مفعما بالولاء الصادق للرب إلهنا، إذ تسلكون بموجب فرائضه وتطيعون وصاياه كما فعلتم اليوم».","8:62":"ثم ذبح الملك وسائر إسرائيل معه ذبائح أمام الرب،","8:63":"وقرب سليمان من ذبائح السلام للرب اثنين وعشرين ألفا من البقر، ومئة ألف وعشرين ألفا من الغنم. وهكذا دشن الملك وجميع بني إسرائيل هيكل الرب.","8:64":"وقدس الملك في ذلك اليوم الفناء الذي يقع أمام الهيكل، بأن قرب هناك المحرقات والتقدمات وشحم ذبائح السلام، لأن مذبح النحاس القائم أمام الرب كان أصغر من أن يسع المحرقات والتقدمات وشحم ذبائح السلام.","8:65":"واحتفل سليمان بالعيد في ذلك الوقت مع سائر إسرائيل وجمهور كبير توافد من مدخل حماة إلى وادي مصر، واستمر الاحتفال أمام الرب أربعة عشر يوما","8:66":"وفي اليوم الخامس عشر بعد العيد، صرف سليمان الشعب، فباركوه وتوجهوا إلى منازلهم بقلوب يغمرها الفرح والغبطة من أجل كل الخيرات التي أبداها الرب نحو داود عبده، ونحو شعبه إسرائيل.","9:1":"وبعد أن أتم سليمان بناء هيكل الرب وقصر الملك، وكل ما رغب أن يقيمه من مبان أخرى.","9:2":"تجلى الرب لسليمان ثانية كما تجلى له في جبعون،","9:3":"وقال له: «سمعت صلاتك وتضرعك الذي رفعته أمامي، لهذا قدست هذا الهيكل الذي شيدته لأضع اسمي عليه إلى الأبد، فتكون عيناي وقلبي هناك كل الأيام.","9:4":"فإن سلكت أنت أمامي كما سلك أبوك داود بكمال القلب والاستقامة، وطبقت كل ما أمرتك به، وأطعت فرائضي وأحكامي،","9:5":"فإني أثبت كرسي ملكك على إسرائيل إلى الأبد، كما وعدت داود أباك قائلا: لا ينقرض من نسلك من يملك على عرش إسرائيل.","9:6":"أما إن انحرفتم أنتم أو أبناؤكم عن اتباعي، ولم تطيعوا وصاياي وفرائضي التي سننتها لكم، وغويتم عابدين آلهة أخرى وسجدتم لها،","9:7":"فإني أبيد إسرائيل عن وجه الأرض التي وهبتها لهم، وأنبذ الهيكل الذي قدسته لاسمي، فيصبح إسرائيل مثلا ومثار هزء لجميع الأمم.","9:8":"ويصبح هذا الهيكل عبرة يثير عجب كل من يمر به، فيصفر ويتساءل: لماذا صنع الرب هكذا بهذه الأرض وبهذا الهيكل؟","9:9":"فيأتيهم الجواب: لأنهم تركوا الرب إلههم الذي أخرج آباءهم من ديار مصر، وتشبثوا بآلهة أخرى وسجدوا لها وعبدوها، لذلك جلب الرب عليهم كل هذا البلاء».","9:10":"وفي نهاية العشرين عاما التي بنى سليمان في أثنائها هيكل الرب وقصر الملك","9:11":"أعطى سليمان حيرام ملك صور عشرين مدينة في أرض الجليل، لأنه أمد سليمان بخشب أرز وخشب سرو وذهب على قدر طلبه.","9:12":"فجاء حيرام من صور ليتفقد المدن التي أعطاها سليمان له، فلم ترق له،","9:13":"فتساءل: «ما هذه المدن التي أعطيتني إياها ياأخي؟» ودعاها «أرض كابول» (ومعناها الأرض غير المثمرة) إلى هذا اليوم.","9:14":"وكان الذهب الذي أرسله حيرام إلى الملك سليمان مئة وعشرين وزنة ذهب (نحو أربعة آلاف وثلاث مئة وعشرين كيلوجراما).","9:15":"أما خدمة التسخير التي فرضها سليمان، فكانت بداعي بناء هيكل الرب، وقصر سليمان، والقلعة، وسور أورشليم، وحاصور ومجدو وجازر.","9:16":"وكان فرعون ملك مصر قد هاجم جازر واستولى عليها وأحرقها بالنار، وقتل أهلها الكنعانيين المقيمين فيها، ثم وهبها مهرا لابنته زوجة سليمان.","9:17":"وأعاد سليمان بناء جازر وبيت حورون السفلى،","9:18":"وبعلة وتدمر في أرض الصحراء،","9:19":"وبنى جميع مدن مخازن غلاته، ومدنا لمركباته، ومدنا لإقامة الفرسان. وهكذا بنى سليمان كل ما رغب فيه في أورشليم وفي لبنان وفي جميع أرجاء سلطنته.","9:20":"أما من تبقى من الأموريين والحثيين والفرزيين والحو يين واليبوسيين الذين لا ينتمون إلى إسرائيل،","9:21":"من ذراري الأمم التي عجز الإسرائيليون عن إفنائهم، فقد فرض عليهم سليمان خدمة التسخير كالعبيد إلى هذا اليوم.","9:22":"أما أبناء إسرائيل فلم يسخر سليمان منهم أحدا، لأن منهم كان يتألف جنوده ورجال حاشيته وأمراؤه وضباطه وقادة مركباته وفرسانه،","9:23":"وكان عدد الموكلين على الإشراف على خدمة العمال المسخرين لتنفيذ أعمال سليمان خمس مئة وخمسين رجلا.","9:24":"وبعد أن انتقلت ابنة فرعون من مدينة داود إلى قصرها الذي بناه لها، عمل سليمان على بناء القلعة.","9:25":"وأخذ سليمان يقرب محرقات وذبائح سلام على المذبح الذي بناه للرب ثلاث مرات في السنة، كما كان يحرق على المذبح الذي أمام الرب. وهكذا أتم بناء الهيكل.","9:26":"وشرع سليمان في بناء سفن في عصيون جابر المجاورة لأيلة على شاطيء البحر الأحمر في أرض أدوم،","9:27":"فأرسل حيرام بحارته المتمرسين بمسالك البحر في تلك السفن مع بحارة سليمان،","9:28":"فبلغوا أوفير حيث جلبوا من هناك أربع مئة وعشرين وزنة (نحو خمسة عشر ألفا ومئة وعشرين كيلوجراما) من الذهب، حملوها إلى الملك سليمان.","10:1":"وعندما بلغت أخبار سليمان وإعلائه لاسم الرب مسامع ملكة سبأ، قدمت لتلقي عليه أسئلة عسيرة،","10:2":"فوصلت أورشليم في موكب عظيم جدا، وجمال محملة بأطياب وذهب وفير وحجارة كريمة، وأسرت إليه بكل ما في نفسها.","10:3":"فأجاب سليمان عن كل أسئلتها، من غير أن يعجز عن شرح شيء.","10:4":"ولما رأت ملكة سبأ كل حكمة سليمان، وشاهدت القصر الذي شيده،","10:5":"وما يقدم على مائدته من طعام، ومجلس رجال دولته، وموقف خدامه وملابسهم، وسقاته ومحرقاته التي كان يقربها في بيت الرب، اعتراها الذهول العميق،","10:6":"فقالت للملك: «إن الأخبار التي بلغتني في أرضي عن أمورك وحكمتك هي حقا صحيحة.","10:7":"ولم أصدقها في باديء الأمر حتى جئت وشاهدت، فوجدت أن ما بلغني لا يجاوز نصف الحقيقة، فقد رأيت أن حكمتك وصلاحك يزيدان عما سمعته من أخبارك.","10:8":"فطوبى لرجالك وطوبى لخدامك الماثلين دائما في حضرتك يسمعون حكمتك.","10:9":"فليتبارك الرب إلهك الذي سر بك، وأجلسك على عرش إسرائيل، لأنه بفضل محبته الأبدية لإسرائيل قد أقامك ملكا لتجري العدل والبر».","10:10":"وأهدت الملك مئة وعشرين وزنة (نحو أربعة آلاف وثلاث مئة وعشرين كيلو جراما) من الذهب وأطيابا كثيرة وحجارة كريمة، فكانت التوابل التي أهدتها ملكة سبأ للملك سليمان من الوفرة بحيث لم يجلب مثلها في ما بعد.","10:11":"وجلبت أيضا سفن حيرام التي حملت الذهب من أوفير، خشب الصندل بكميات وافرة جدا وحجارة كريمة،","10:12":"فصنع سليمان من خشب الصندل درابزينا لهيكل الرب وللقصر، كما صنع منه أعوادا وقيثارات. ولم ير ولم يجلب حتى اليوم مثل خشب الصندل ذلك لكثرته.","10:13":"وأعطى الملك سليمان ملكة سبأ كل ما رغبت فيه، فضلا عما أهداه إليها وفقا لكرمه. ثم انصرفت هي وحاشيتها إلى أرضها.","10:14":"وكان وزن الذهب الذي حصل عليه سليمان في سنة واحدة ست مئة وستا وستين وزنة ذهب (نحو ثلاثة وعشرين ألفا وتسع مئة وستة وسبعين كيلوجراما).","10:15":"فضلا عن عوائد ضرائب التجار وأرباح تجارته مع ملوك العرب وولاة الأرض.","10:16":"وصنع سليمان مئتي ترس من الذهب المطروق، استهلك كل ترس منها ست مئة شاقل (نحو ثلاثة كيلوجرامات ونصف الكيلوجرام) من الذهب.","10:17":"وثلاث مئة درع من ذهب مطروق، استهلك كل درع منها ثلاثة أمناء من الذهب (نحو كيلو وثماني مئة جرام)، وجعلها سليمان في قصر غابة لبنان.","10:18":"وصنع سليمان عرشا عظيما من عاج، غشاه بذهب إبريز.","10:19":"وكان للعرش ست درجات، وله رأس مستدير من الخلف، ومسندان على جانبيه حول موضع الجلوس، وأسدان يقفان إلى جوار المسندين.","10:20":"وأقيم على الدرجات الست اثنا عشر أسدا، ست على كل جانب، فلم يكن لهذا العرش نظير في كل الممالك.","10:21":"أما جميع آنية شرب الملك سليمان، وسائر آنية قصر غابة لبنان، فكانت كلها مصنوعة من الذهب الخالص، فالفضة لم يكن لها قيمة في أيام سليمان.","10:22":"وكان للملك أسطول بحري تجاري يعمل بالمشاركة مع أسطول حيرام. فكان هذا الأسطول التجاري يأتي مرة كل ثلاث سنوات محملا بالذهب والفضة والعاج والقرود والطواويس ويفرغها في إسرائيل.","10:23":"وهكذا تعاظم شأن الملك سليمان على كل ملوك الأرض من حيث الغنى والحكمة،","10:24":"وتوافد الناس من جميع أرجاء الأرض للمثول في حضرة سليمان والاستماع إلى حكمته التي أودعها الله في قلبه،","10:25":"فكان كل واحد يأتي حاملا هدايا من أوان فضية وذهبية، وحلل وسلاح وتوابل وخيل وبغال سنة بعد سنة","10:26":"وتجمع لدى سليمان مراكب وفرسان، فكانت له ألف وأربع مئة مركبة، واثنا عشر ألف فارس، فوزعهم على مدن المركبات، واحتفظ ببعض منهم معه في أورشليم.","10:27":"وأصبحت الفضة في أورشليم كالحصى لكثرتها، كما صار خشب الأرز لتوفره لا يزيد قيمة عن خشب الجميز.","10:28":"وقد استوردت خيل سليمان من مصر ومن تقوع، وكان تجار الملك يتسلمونها من تقوع بثمن معين.","10:29":"وشرع تجار الملك يستوردون المركبات من مصر، فيدفعون ست مئة شاقل (نحو سبعة كيلوجرامات) من الفضة عن كل مركبة، ومئة وخمسين شاقلا (نحو كيلوجرامين) عن كل فرس. ثم يصدرونها لجميع ملوك الحثيين وملوك الأراميين.","11:1":"وأولع سليمان بنساء غريبات كثيرات، فضلا عن ابنة فرعون، فتزوج نساء موآبيات وعمونيات وأدوميات وصيدونيات وحثيات،","11:2":"وكلهن من بنات الأمم التي نهى الرب بني إسرائيل عن الزواج منهم قائلا لهم: «لا تتزوجوا منهم ولا هم منكم، لأنهم يغوون قلوبكم وراء آلهتهم». ولكن سليمان التصق بهن لفرط محبته لهن.","11:3":"فكانت له سبع مئة زوجة، وثلاث مئة محظية، فانحرفن بقلبه عن الرب.","11:4":"فاستطعن في زمن شيخوخته أن يغوين قلبه وراء آلهة أخرى، فلم يكن قلبه مستقيما مع الرب إلهه كقلب داود أبيه.","11:5":"وما لبث أن عبد عشتاروث آلهة الصيدونيين، وملكوم إله العمونيين البغيض،","11:6":"وارتكب الشر في عيني الرب، ولم يتبع سبيل الرب بكمال كما فعل أبوه داود.","11:7":"وأقام على تل شرقي أورشليم مرتفعا لكموش إله الموآبيين الفاسق، ولمولك إله بني عمون البغيض.","11:8":"وشيد مرتفعات لجميع نسائه الغريبات، اللواتي رحن يوقدن البخور عليها ويقربن المحرقات لآلهتهن.","11:9":"فغضب الرب على سليمان لأن قلبه ضل عنه، مع أنه تجلى له مرتين،","11:10":"ونهاه عن الغواية وراء آلهة أخرى، فلم يطع وصيته.","11:11":"لهذا قال الله لسليمان: «لأنك انحرفت عني ونكثت عهدي، ولم تطع فرائضي التي أوصيتك بها، فإني حتما أمزق أوصال مملكتك، وأعطيها لأحد عبيدك.","11:12":"إلا أنني لا أفعل هذا في أيامك، من أجل داود أبيك، بل من يد ابنك أمزقها.","11:13":"غير أني أبقي له سبطا واحدا، يملك عليه إكراما لداود عبدي، ومن أجل أورشليم التي اخترتها».","11:14":"وأثار الرب على سليمان هدد سليل النسل الملكي الأدومي،","11:15":"ففيما كان داود في أدوم، صعد يوآب رئيس الجيش لدفن القتلى، وقضى على كل ذكر في أدوم.","11:16":"إذ إن يوآب وكل جيشه أقاموا هناك ستة أشهر، أفنوا خلالها كل ذكر في أدوم،","11:17":"ولكن هدد وبعض رجال أبيه الأدوميين استطاعوا الهرب واللجوء إلى مصر، وكان هدد آنئذ فتى صغيرا.","11:18":"وأقاموا في باديء الأمر في مديان، ثم انتقلوا إلى فاران حيث انضم إليهم عدد آخر من الرجال، توجهوا جميعا إلى فرعون مصر، فأعطى فرعون هدد بيتا وأرضا وطعاما،","11:19":"وحظي هدد برضى فرعون، فزوجه أخت امرأته الملكة تحفنيس،","11:20":"فأنجبت له أخت تحفنيس ابنا دعاه جنوبث. وفطمته تحفنيس في قصر فرعون، وهكذا نشأ جنوبث في بيت فرعون بين أبنائه.","11:21":"وعندما سمع هدد في مصر بموت داود ومصرع يوآب رئيس الجيش، قال لفرعون: «دعني أمضي إلى أرضي».","11:22":"فقال له فرعون: «هل افتقرت إلى شيء عندي حتى تنشد الرجوع إلى أرضك؟» فأجاب: «لا شيء إنما دعني أنطلق».","11:23":"وأثار الله على سليمان خصما آخر هو رزون بن أليداع، الذي هرب من عند سيده هدد عزر ملك صوبة،","11:24":"فضم إليه رجالا، وأصبح رئيسا لعصابة من الثوار، في الحقبة التي دمر فيها داود قوات صوبة. فانطلق رزون بعصابته إلى دمشق وأقاموا فيها واستولوا عليها.","11:25":"وظل رزون خصما لإسرائيل طوال حياة سليمان، فضلا عما خلقه هدد من متاعب. وهكذا ملك رزون في دمشق وبقي عدوا لإسرائيل.","11:26":"وتمرد يربعام بن ناباط الأفرايمي من صردة، وكان من رجال سليمان، واسم أمه صروعة وهي أرملة.","11:27":"أما سبب تمرده على الملك فهو أن سليمان بنى القلعة وسد الثغرات في سور مدينة داود أبيه،","11:28":"وكان يربعام رجلا شديد المراس. فلما رأى سليمان أن الشاب نشيط مجتهد، أقامه مشرفا على أعمال التسخير في أرض سبط يوسف.","11:29":"وحدث أن يربعام خرج من أورشليم، فالتقاه النبي أخيا الشيلوني في الطريق. وكان النبي يرتدي رداء جديدا، ولم يكن سواهما في الحقل،","11:30":"فتناول أخيا الر داء الجديد الذي عليه ومزقه اثنتي عشرة قطعة،","11:31":"وقال ليربعام: «خذ لنفسك عشر قطع، لأنه هكذا يقول الرب إله إسرائيل: ها أنا أمزق المملكة من يد سليمان وأعطيك عشرة أسباط،","11:32":"ولا يبقى له سوى سبط واحد إكراما لعبدي داود، ومن أجل أورشليم المدينة التي اخترتها من بين مدن إسرائيل.","11:33":"لأنه تخلى عني وسجد لعشتاروث إلاهة الصيدونيين، ولكموش إله الموآبيين، ولملكوم إله بني عمون، ولم يسلك في سبلي، ويصنع ما هو مستقيم في عيني، ولم يطع فرائضي وأحكامي كداود أبيه.","11:34":"ولكني لن أنزع كل الملك عنه، بل أبقيه رئيسا طوال حياته من أجل داود عبدي الذي اخترته، فحفظ وصاياي وفرائضي.","11:35":"إنما أمزق المملكة من يد ابنه، وأوليك على عشرة أسباط منها،","11:36":"تاركا لابنه سبطا واحدا، ليظل أمامي دائما سراج لداود عبدي في أورشليم، المدينة التي اخترتها لنفسي لأضع اسمي عليها.","11:37":"أما أنت فأنصبك ملكا لتحكم على إسرائيل وفقا لرغبة نفسك.","11:38":"فإن أطعت كل ما آمرك به وسلكت في سبلي، وصنعت ما هو صالح في عيني، وحفظت فرائضي ووصاياي كما فعل داود عبدي، أكون معك وأرسخ لك ملكا آمنا كما بنيت لداود، وأعطيك إسرائيل.","11:39":"وأذل ذرية داود إلى حين من أجل هذا الإثم».","11:40":"وسعى سليمان إلى قتل يربعام، فلجأ يربعام إلى شيشق ملك مصر ومكث هناك حتى وفاة سليمان.","11:41":"أما بقية أعمال سليمان وكل ما صنع، وأقوال حكمته، أليست هي مدونة في كتاب تاريخ سليمان؟","11:42":"ودام ملك سليمان في أورشليم على إسرائيل أربعين سنة.","11:43":"ثم مات سليمان، فدفن مع أسلافه في مدينة داود أبيه، وخلفه ابنه رحبعام على العرش.","12:1":"وذهب رحبعام إلى شكيم، فتوافد إلى هناك جميع بني إسرائيل لينصبوه ملكا.","12:2":"وعندما سمع يربعام بن نباط وهو في مصر، التي لجأ إليها ومكث فيها هربا من سليمان، رجع منها،","12:3":"فأرسلوا يستدعونه. فجاء يربعام وكل جماعة إسرائيل، وقالوا لرحبعام:","12:4":"«إن أباك أثقل النير علينا، فخفف أنت الآن من عبئنا المرهق، ومن ثقل النير الذي وضعه أبوك على كاهلنا، فنخدمك».","12:5":"فأجابهم: «اذهبوا الآن ثم ارجعوا إلي بعد ثلاثة أيام». فانصرف الشعب.","12:6":"فسأل رحبعام الشيوخ الذين كانوا في خدمة أبيه سليمان: «بماذا تشيرون أن أرد جوابا إلى هذا الشعب؟»","12:7":"فأجابوه: «إن صرت خادما لهذا الشعب، وراعيتهم، وتجاوبت معهم، وأحسنت مخاطبتهم، يصبحون لك عبيدا كل الأيام».","12:8":"ولكنه لم يتبع مشورة الشيوخ، بل تداول مع الأحداث الذين نشأوا معه، وكانوا من جملة حاشيته،","12:9":"وسألهم: «بم تشيرون أنتم فنرد جوابا إلى هذا الشعب الذي طالبني قائلا: خفف من النير الذي أثقل به أبوك كاهلنا».","12:10":"فأجابوه: «تقول لهذا الشعب الذي طالبك بتخفيف نير أبيك عنهم: إن خنصري أغلظ من خاصرة أبي.","12:11":"أبي أثقل عليكم النير وأنا أضاعفه. أبي أدبكم بالسياط وأنا أؤدبكم بالعقارب».","12:12":"وفي اليوم الثالث مثل يربعام وسائر الشعب أمام رحبعام، كما طلب إليهم الملك.","12:13":"وتلقوا رده القاسي الذي تجاهل فيه مشورة الشيوخ،","12:14":"وخاطبهم بما أشار عليه الأحداث قائلا: «أبي أثقل عليكم النير وأنا أضاعفه. أبي أدبكم بالسياط، وأنا أؤدبكم بالعقارب».","12:15":"ورفض رحبعام الاستجابة لمطالب الشعب، وكان ذلك من الرب لينفذ ما تكلم به على لسان أخيا الشيلوني بشأن يربعام بن نباط.","12:16":"فلما رأى كل بني إسرائيل أن الملك لم يستجب لمطالبهم، أجابوه: «أي نصيب لنا في داود، وأي حظ لنا بابن يسى؟ فإلى بيوتك ياإسرائيل. وليملك رحبعام على أهله وعشيرته». وانصرف الإسرائيليون عنه إلى منازلهم.","12:17":"ولم يبق تحت حكمه سوى أبناء إسرائيل المقيمين في مدن يهوذا، فملك رحبعام عليهم.","12:18":"وعندما أرسل الملك رحبعام أدورام الموكل على أعمال التسخير إلى أسباط إسرائيل رجموه بالحجارة فمات، فبادر الملك رحبعام واستقل مركبته هاربا إلى أورشليم.","12:19":"وهكذا تمرد إسرائيل على ذرية داود إلى هذا اليوم.","12:20":"وعندما علم جميع بني إسرائيل برجوع يربعام من مصر، استدعوه للمثول أمام جماعة إسرائيل، ونصبوه ملكا عليهم، ولم يبق تحت حكم رحبعام سوى سبط يهوذا.","12:21":"وحين وصل رحبعام أورشليم حشد جيشا من سبطي يهوذا وبنيامين، بلغ عدده مئة وثمانين ألفا من نخبة المقاتلين، ليحارب بني إسرائيل ويردهم إلى ملكه.","12:22":"ولكن الله خاطب شمعيا النبي:","12:23":"«قل لرحبعام بن سليمان وسائر شعب يهوذا وبنيامين","12:24":"هذا ما يأمر به الرب: لا تذهبوا لمحاربة إخوتكم بني إسرائيل. ليرجع كل واحد منكم إلى منزله، لأن من عندي قد صدر الأمر بتمزيق المملكة». فاستجابوا لأمر الرب، وأذعنوا له.","12:25":"وحصن يربعام مدينة شكيم في جبل أفرايم وأقام فيها؛ ثم انطلق من هناك وبنى مدينة فنوئيل.","12:26":"وحدث يربعام نفسه قائلا: «من المرجح أن ترجع المملكة إلى بيت داود،","12:27":"ولاسيما إن صعد الشعب ليقربوا ذبائح في هيكل الرب في أورشليم، فيميل قلبهم نحو سيدهم رحبعام ملك يهوذا ويقتلونني، ثم يلتفون حوله».","12:28":"وبعد المشاورة سبك الملك عجلي ذهب، وقال للشعب: «إن الذهاب إلى أورشليم للعبادة يعرضكم لمشقة عظيمة، فها هي آلهتك ياإسرائيل التي أخرجتك من ديار مصر».","12:29":"وأقام واحدا في بيت إيل والآخر في دان.","12:30":"فصار هذا العمل إثما كبيرا، لأن الشعب شرع في عبادة العجلين حتى ولو اضطر بعضهم للارتحال إلى دان.","12:31":"وشيد يربعام مذابح عبادة على التلال، كرس لها كهنة من عامة الشعب، لا ينتمون إلى سبط لاوي.","12:32":"واحتفل يربعام بعيد في اليوم الخامس عشر من الشهر الثامن (تشرين الثاني ; نوفمبر)، مثل العيد الذي يحتفل به في يهوذا، وقدم محرقات على المذبح. وقرب في بيت إيل ذبائح للعجلين اللذين سبكهما. كما نصب في بيت إيل كهنة للمرتفعات التي أقامها.","12:33":"وهكذا أصعد محرقات على المذبح الذي بناه في بيت إيل في اليوم الخامس عشر من الشهر الثامن، الذي اختاره بنفسه، وجعله عيدا يحتفل به بنو إسرائيل. وصعد هو بنفسه إلى المذبح ليوقد عليه.","13:1":"وبينما كان يربعام واقفا عند المذبح ليوقد عليه، أقبل رجل الله من يهوذا إلى بيت إيل حاملا رسالة من الرب.","13:2":"وهتف مخاطبا المذبح بقضاء الرب قائلا: «يامذبح، يامذبح، هذا ما يقوله الرب: سيولد لبيت داود ابن يدعى يوشيا، فيذبح عليك كهنة المرتفعات الذين يقربون عليك، وتحرق فوقك عظام الناس».","13:3":"وتأييدا لكلامه أعطى في ذلك اليوم علامة تؤكد أن الرب هو الذي تكلم، وقال: «هوذا المذبح ينشق ويذرى الرماد الذي عليه».","13:4":"فلما سمع الملك كلام رجل الله الذي خاطب به المذبح في بيت إيل، رفع يده من على المذبح، ومدها نحو النبي صارخا: «اقبضوا عليه» فيبست يده التي مدها وعجز عن ردها.","13:5":"وانشق آنئذ المذبح وذري الرماد من عليه وفقا للعلامة التي أعطاها رجل الله بمقتضى أمر الرب.","13:6":"عندئذ توسل الملك لرجل الله قائلا: «تضرع إلى الرب إلهك، وصل من أجلي لترتد يدي إلى طبيعتها». فابتهل رجل الله إلى الرب، فارتدت يد الملك إلى ما كانت عليه.","13:7":"ثم قال الملك لرجل الله: «تعال معي إلى قصري لتقتات وأعطيك مكافأة».","13:8":"فأجابه: «حتى لو وهبتني نصف قصرك فلن أطأ أرضه، ولا آكل خبزا ولا أشرب ماء في هذا الموضع.","13:9":"لأن الرب أمرني قائلا: «لا تأكل خبزا ولا تشرب ماء ولا ترجع في نفس الطريق التي جئت منها».","13:10":"ثم انصرف في طريق أخرى غير التي سلكها في مجيئه إلى بيت إيل.","13:11":"وكان هناك نبي شيخ مقيما في بيت إيل، فجاء أبناؤه وسردوا عليه كل ما أجراه رجل الله من آيات في ذلك اليوم في بيت إيل، وحدثوه بما خاطب به الملك.","13:12":"فسألهم أبوهم: «من أي طريق انصرف؟» فأخبروه، لأنهم كانوا قد رأوا الطريق التي انصرف فيها.","13:13":"فقال لأبنائه: «أسرجوا لي الحمار». وعندما فعلوا ركب عليه.","13:14":"واقتفى أثره حتى أدركه جالسا تحت البلوطة. فسأله: «هل أنت رجل الله الذي وفد من يهوذا؟» فأجابه: «أنا هو».","13:15":"فقال له: «تعال معي إلى البيت لتأكل طعاما».","13:16":"فأجابه: «لا أستطيع أن أرجع معك أو أدخل بيتك أو آكل طعاما أو أشرب ماء في هذا الموضع،","13:17":"لأن الرب أمرني قائلا: لا تأكل طعاما ولا تشرب ماء ولا تنصرف في نفس الطريق التي جئت منها».","13:18":"فقال له: «أنا أيضا نبي مثلك وقد أمرني ملاك الرب أن أرجع بك معي إلى بيتي فتقتات وتشرب ماء». وهكذا كذب عليه.","13:19":"(فصدقه) ورجع معه وتناول طعاما في بيته وشرب ماء.","13:20":"وفيما هما جالسان حول المائدة يتناولان الطعام، خاطب الرب النبي الشيخ،","13:21":"فقال لرجل الله الوافد من يهوذا: «هذا ما يقوله الرب: لأنك خالفت أمر الرب ولم تطع وصيته التي أوصاك بها الرب إلهك،","13:22":"فرجعت وأكلت طعاما وشربت ماء في الموضع الذي حذرك منه قائلا: لا تأكل فيه طعاما ولا تشرب ماء، فإن جثتك لن تدفن في قبر آبائك».","13:23":"وبعد أن تناول نبي يهوذا طعاما وشرب ماء، أسرج له مضيفه حماره.","13:24":"وبينما هو منصرف في طريقه صادفه أسد وقتله، وظلت جثته مطروحة في الطريق، والحمار والأسد واقفان إلى جوار الجثة.","13:25":"ومر قوم فشاهدوا الجثة مطروحة في الطريق والأسد واقف إلى جوارها فأتوا وأذاعوا الخبر في المدينة التي يقيم فيها النبي الشيخ.","13:26":"وعندما سمع النبي الشيخ بالنبإ قال: «هو حتما رجل الله الذي خالف أمر الرب، فأوقعه الرب بين مخالب الأسد فافترسه وقتله تحقيقا لقضائه الذي نطق به».","13:27":"وقال لأبنائه: «أسرجوا لي الحمار». فأسرجوه،","13:28":"فانطلق إلى حيث عثر على الجثة مطروحة في الطريق، والأسد والحمار واقفين إلى جوارها، من غير أن يأكل الأسد الجثة أو يفترس الحمار،","13:29":"فوضع النبي جثة رجل الله على الحمار، ومضى بها إلى المدينة، ليندبه","13:30":"ثم دفنها في قبره وهو ينوح قائلا: «آه عليك ياأخي».","13:31":"وبعد أن تم دفن جثة رجل الله، قال النبي الشيخ لأبنائه: «عند وفاتي ادفنوني في القبر الذي دفن فيه رجل الله، وضعوا عظامي إلى جوار عظامه،","13:32":"لأن ما أنذر به من كلام الرب بشأن المذبح الذي في بيت إيل، وجميع معابد المرتفعات التي في مدن السامرة، لابد أن يتحقق».","13:33":"وعلى الرغم من تحذير النبي فإن يربعام لم يحد عن طريقه الأثيمة، بل عاد مرة أخرى فكرس كهنة لمعابد المرتفعات، اختارهم من عامة الشعب، فكان يكرس كل من يرغب أن يكون كاهنا لهذه المرتفعات.","13:34":"فكانت هذه هي خطيئة بيت يربعام التي أفضت إلى سقوطه وانقراضه عن وجه الأرض.","14:1":"في ذلك الوقت مرض أبيا بن يربعام،","14:2":"فقال يربعام لزوجته: «تنكري حتى لا يكتشف أحد أنك زوجتي، وامضي إلى شيلوه حيث يقيم أخيا الذي أنبأني أنني سأملك على هذا الشعب،","14:3":"وخذي له معك عشرة أرغفة وكعكا وجرة عسل، وانطلقي إليه وهو يخبرك بمصير الغلام».","14:4":"فنفذت زوجة يربعام ما طلبه منها، ووصلت إلى بيت أخيا في شيلوه، وكان أخيا قد طعن في السن، وكل بصره.","14:5":"وقال الرب لأخيا: «ها هي زوجة يربعام مقبلة لتسألك عن مصير ابنها المريض، فأجبها بما أقوله لك، لأنها ستدخل إليك متنكرة».","14:6":"فلما سمع أخيا وقع خطواتها وهي داخلة من الباب قال: «ادخلي يا زوجة يربعام. لماذا تتنكرين؟ إنني أحمل إليك أخبارا سيئة.","14:7":"اذهبي وبلغي يربعام قضاء الرب إله إسرائيل: لقد رفعتك من وسط الشعب، ونصبتك رئيسا على شعبي إسرائيل،","14:8":"ومزقت المملكة عن بيت داود ووليتك عليها، ولكنك لم تكن كعبدي داود الذي حفظ وصاياي وتبعني من كل قلبه ليصنع ما هو صالح في عيني.","14:9":"لقد ارتكبت من السيئات ما فاق جميع الذين كانوا قبلك، فصنعت لنفسك آلهة أخرى، أصناما مسبوكة، لتثير غيظي، وقد طرحتني خلف ظهرك.","14:10":"لذلك ها أنا مزمع أن أبتلي بيتك بشر عظيم، وأبيد كل ذكر من نسلك، عبدا كان أم حرا، وأفني بيتك كما تفني النار الروث الجاف،","14:11":"فتأكل الكلاب كل من يموت لك في المدينة، وتنهش طيور السماء كل من يموت لك في الحقل، لأن الرب تكلم».","14:12":"وأضاف أخيا: «أما أنت فانهضي وانطلقي إلى بيتك، وحالما تدخلين المدينة يموت الولد،","14:13":"فينوح عليه الإسرائيليون ويدفنونه، لأن هذا وحده من نسل يربعام يوارى في قبر، لأن الرب إله إسرائيل قد وجد فيه، من دون سائر بيت يربعام، شيئا صالحا.","14:14":"ويقيم الرب لنفسه ملكا على إسرائيل ليبيد بيت يربعام اليوم.","14:15":"ثم يعصف الرب بإسرائيل، فيهزهم كاهتزاز القصب في الماء، ويستأصلهم من هذه الأرض الخيرة التي وهبها لآبائهم، ويشتتهم إلى ما وراء النهر لأنهم أقاموا لأنفسهم أصناما وأثاروا غيظ الرب.","14:16":"وينبذ إسرائيل من جراء خطايا يربعام التي ارتكبها واستغوى إسرائيل معه فأخطأوا».","14:17":"فعادت زوجة يربعام إلى ترصة. وما إن وصلت إلى عتبة باب البيت حتى مات الغلام،","14:18":"فدفنه الإسرائيليون وناحوا عليه، تماما حسب كلام الرب الذي نطق به على لسان عبده أخيا النبي.","14:19":"أما بقية أعمال يربعام وكيف حارب وكيف ملك، فهي مدونة في كتاب أخبار أيام ملوك إسرائيل.","14:20":"ودام ملك يربعام اثنتين وعشرين سنة، ثم مات ودفن مع آبائه، وخلفه على العرش ابنه ناداب.","14:21":"أما رحبعام بن سليمان فقد ملك في يهوذا وكان عمره إحدى وأربعين سنة حين ملك، واستمر حكمه سبع عشرة سنة في أورشليم، المدينة التي اختارها الرب من بين جميع مدن إسرائيل ليضع اسمه عليها، وكان اسم أمه نعمة العمونية.","14:22":"وارتكب شعب يهوذا الشر في عيني الرب، فاستثاروا غيظه كما لم تستثره خطايا آبائهم التي ارتكبوها.","14:23":"وأقاموا هم أيضا لأنفسهم مرتفعات وأنصابا وتماثيل على كل تل مرتفع، وتحت كل شجرة خضراء.","14:24":"وتكاثر في الأرض العاهرون من ذوي الشذوذ الجنسي، واقترفوا كل موبقات الأمم التي طردها الرب من أمام بني إسرائيل.","14:25":"وفي السنة الخامسة للملك رحبعام هاجم شيشق ملك مصر أورشليم.","14:26":"واستولى على خزائن بيت الرب وخزائن قصر الملك، وسلب كل ما فيها، لاسيما الأتراس الذهبية التي عملها سليمان.","14:27":"فصنع الملك رحبعام عوضا عنها أتراسا نحاسية، سلمها لرؤساء حرس باب قصر الملك.","14:28":"فكان كلما دخل الملك إلى هيكل الرب يحملها الحراس أمامه، ثم يعيدونها إلى غرفة الحرس.","14:29":"أما بقية أحداث حياة رحبعام وكل ما قام به من أعمال، أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟","14:30":"وظلت رحى الحرب دائرة بين رحبعام ويربعام طوال حياة رحبعام.","14:31":"ثم مات رحبعام ودفن مع آبائه في مدينة داود، واسم أمه نعمة العمونية وخلفه ابنه أبيام على العرش.","15:1":"وفي السنة الثامنة عشرة من حكم الملك يربعام بن نباط، اعتلى أبيام عرش يهوذا،","15:2":"ودام ملكه ثلاث سنوات في أورشليم، واسم أمه معكة ابنة أبشالوم.","15:3":"وارتكب جميع خطايا أبيه التي اقترفها قبله، ولم يكن قلبه مخلصا للرب إلهه كقلب داود أبيه.","15:4":"إلا أن الرب إلهه إكراما لداود، رزقه ابنا في أورشليم، فأورثه الملك وثبت أركان أورشليم،","15:5":"لأن داود صنع ما هو صالح في عيني الرب، ولم يحد عن كل ما أمره به كل أيام حياته، إلا ما جناه بحق أوريا الحثي.","15:6":"وخلال فترة حكم أبيام كانت الحروب مستمرة بين إسرائيل ويهوذا.","15:7":"أما بقية أعمال أبيام ومنجزاته أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟","15:8":"ثم مات أبيام، فدفن مع آبائه في مدينة داود، وخلفه ابنه آسا على العرش.","15:9":"وكان ذلك في السنة العشرين من حكم يربعام ملك إسرائيل.","15:10":"وملك آسا إحدى وأربعين سنة في أورشليم، واسم جدته معكة ابنة أبشالوم،","15:11":"وصنع آسا ما هو صالح في عيني الرب كداود أبيه","15:12":"وأباد من الأرض طائفة العاهرين الذين يمارسون الشذوذ الجنسي كجزء من عبادتهم الوثنية، واستأصل جميع الأصنام التي أقامها آباؤه.","15:13":"كما خلع جدته معكة من منصب الأم الملكة، لأنها أقامت تمثالا لعشتاروث، فانتزع آسا تمثالها وأحرقه في وادي قدرون.","15:14":"أما مذابح المرتفعات فلم يهدمها، إلا أن قلبه كان خالص الولاء للرب كل أيامه.","15:15":"وجاء بكل ما خصصه أبوه وما خصصه هو من ذهب وفضة وسواها من الآنية إلى هيكل الرب.","15:16":"وظلت الحرب دائرة بين آسا وبعشا ملك إسرائيل طوال أيام حياتهما.","15:17":"وشرع الملك بعشا في بناء مدينة الرامة، لقطع الطريق على الخارجين والداخلين إلى آسا ملك يهوذا،","15:18":"فجمع آسا بقية الذهب والفضة الموجودة في خزائن بيت الرب وخزائن قصره، وأعطاها لرجاله، وأرسلهم إلى بنهدد بن طبريمون بن حزيون ملك أرام المقيم في دمشق قائلا:","15:19":"«إن بيني وبينك، وبين أبي وأبيك عهدا، وها أنا باعث إليك هدية من فضة وذهب، فهيا انكث عهدك مع بعشا ملك إسرائيل فيكف عني».","15:20":"فلبى بنهدد طلب آسا، وأرسل رؤساء جيوشه فهاجموا مدن إسرائيل. فدمر مدن عيون ودان وآبل بيت معكة وكل منطقة كنروت وسائر أرض نفتالي.","15:21":"وعندما بلغت بعشا أنباء الهجوم، كف عن بناء الرامة وأقام في ترصة.","15:22":"واستدعى الملك آسا كل رجال يهوذا ولم يعف أحدا، فحملوا كل حجارة الرامة وأخشابها التي استخدمها بعشا في بناء الرامة وشيد بها الملك آسا جبع بنيامين والمصفاة.","15:23":"أما بقية أخبار آسا وكل إنجازاته وما قام به من أعمال وما بناه من مدن، أليست هي مدونة في كتاب أخبار أيام ملوك يهوذا؟ وأصيب الملك آسا في شيخوخته بداء في رجليه.","15:24":"وعندما مات دفن مع آبائه في مدينة داود، وخلفه ابنه يهوشافاط على العرش.","15:25":"وفي السنة الثانية لحكم آسا ملك يهوذا، اعتلى ناداب بن يربعام عرش إسرائيل، ودام ملكه سنتين.","15:26":"وارتكب الشر في عيني الرب، وسلك في سبل أبيه الشريرة التي أفضت ببني إسرائيل إلى اقتراف الإثم.","15:27":"وتمرد عليه بعشا بن أخيا من بيت يساكر، واغتاله بينما كان ناداب وجيش الإسرائيليين يحاصرون مدينة جبثون الفلسطينية.","15:28":"وقد اغتاله بعشا في السنة الثالثة لحكم آسا ملك يهوذا، وخلفه على العرش.","15:29":"وما إن تولى زمام الملك حتى أباد كل ذرية يربعام، ولم يبق على نسمة منهم، تحقيقا لقضاء الرب الذي نطق به على لسان عبده أخيا الشيلوني،","15:30":"بسبب آثام يربعام التي ارتكبها واستغوى بها بني إسرائيل فأخطأوا، فأثار غيظ إله إسرائيل.","15:31":"أما بقية أخبار ناداب وسائر أعماله، أليست هي مدونة في كتاب أخبار أيام ملوك إسرائيل؟","15:32":"وظلت رحى الحرب دائرة بين آسا وبعشا ملك إسرائيل طوال حياتهما.","15:33":"وتولى بعشا بن أخيا حكم إسرائيل في ترصة في السنة الثالثة من ملك آسا على يهوذا، ودام حكمه أربعا وعشرين سنة.","15:34":"وارتكب الشر في عيني الرب وسلك في طرق يربعام وفي خطيئته التي جعلت بني إسرائيل يقترفون الإثم.","16:1":"وأوحى الرب إلى النبي ياهو بن حناني برسالة ليبلغها لبعشا:","16:2":"«لقد رفعتك من الحضيض، ونصبتك ملكا على شعبي ولكنك سلكت في سبل يربعام، وجعلت شعبي يأثمون ويثيرون غيظي بخطاياهم.","16:3":"لهذا سأستأصل ذريتك وسائر نسل بيتك، وأبيد بيتك كما أبدت بيت يربعام بن نباط.","16:4":"فكل من يموت من ذريتك في المدينة تأكله الكلاب، ومن يموت منهم في الحقل تنهشه طيور السماء».","16:5":"أما بقية أخبار بعشا وما قام به من أعمال وبأس، أليست هي مدونة في كتاب أخبار أيام ملوك إسرائيل.","16:6":"ومات بعشا ودفن في ترصة وخلفه ابنه أيلة على عرش إسرائيل.","16:7":"وكان كلام الرب أيضا على لسان ياهو بن حناني النبي بشأن بعشا وذريته بسبب ما ارتكبه من شر في عيني الرب، فأثار غيظه بما جنته يداه، على مثال ما اقترفه بيت يربعام، بل فاق عليه إذ أقدم على إبادة عائلة يربعام.","16:8":"وفي السنة السادسة والعشرين من حكم آسا ملك يهوذا، اعتلى أيلة بن بعشا في ترصة عرش إسرائيل لمدة سنتين.","16:9":"فتآمر عليه زمري قائد نصف فرقة المركبات بينما كان في ترصة يشرب ويسكر في منزل أرصا المشرف على إدارة القصر.","16:10":"فاقتحم زمري المنزل واغتال أيلة. وكان ذلك في السنة السابعة والعشرين من حكم آسا ملك يهوذا وخلفه على عرش إسرائيل.","16:11":"وحالما تسلم زمام الملك أباد كل ذرية بعشا، فلم يبق على ذكر منهم، كما قتل المقربين إلى بعشا وأصحابه.","16:12":"وهكذا أباد زمري كل بيت بعشا، تحقيقا لقضاء الرب على لسان ياهو النبي،","16:13":"وذلك من أجل ما ارتكبه بعشا وابنه أيلة من آثام، وجعلا بني إسرائيل يخطئون، ويستثيرون غيظ الرب إله إسرائيل بضلالهم.","16:14":"أما بقية أخبار أيلة وكل ما قام به من أعمال، أليست هي مدونة في كتاب أخبار أيام ملوك إسرائيل؟","16:15":"وفي السنة السابعة والعشرين لحكم آسا ملك يهوذا، تربع زمري على كرسي المملكة لمدة سبعة أيام في ترصة. وكان الجيش آنئذ يحاصر المدينة الفلسطينية جبثون.","16:16":"فبلغ مسامع الجيش الإسرائيلي أن زمري تمرد على الملك واغتاله، فنصب الجيش قائدهم عمري ملكا على إسرائيل في ذلك اليوم، وهم ما برحوا في ميدان القتال.","16:17":"فتوجه عمري وكل الجيش الذي معه من جبثون وحاصروا ترصة.","16:18":"وعندما رأى زمري أن المدينة قد سقطت، دخل قصر الملك وأشعل فيه وفي نفسه النار، فمات،","16:19":"عقابا على آثامه التي اقترفها حين ارتكب الشر في عيني الرب، وسلك في سبل يربعام، ولأ نه جعل بني إسرائيل يخطئون.","16:20":"أما بقية أخبار زمري وتمرده أليست هي مدونة في كتاب أخبار أيام ملوك إسرائيل؟","16:21":"وما لبث الشعب أن انقسم إلى فئتين: فئة تناصر تبني بن جينة لتبايعه على الملك، وفئة تناصر عمري.","16:22":"فتغلب أنصار عمري على أنصار تبني بن جينة، فمات تبني وسلم العرش لعمري.","16:23":"وفي السنة الواحدة والثلاثين لحكم آسا ملك يهوذا، اعتلى عمري عرش مملكة إسرائيل، ودام حكمه اثنتي عشرة سنة، منها ست سنوات في ترصة.","16:24":"ثم اشترى جبل السامرة من شامر بوزنتين من الفضة (نحو اثنين وسبعين كيلوجراما)، وبنى عليه مدينة دعاها السامرة، على اسم شامر صاحب الجبل.","16:25":"وارتكب عمري الشر في عيني الرب حتى فاق إثمه جميع الذين قبله،","16:26":"واقترف خطايا يربعام بن نباط، وسلك في سبله التي أضل بها إسرائيل فاستثاروا بضلالهم غيظ الرب إلههم.","16:27":"أما بقية أخبار عمري وما قام به من أعمال ومن بأس، أليست هي مدونة في كتاب أخبار أيام ملوك إسرائيل؟","16:28":"ومات عمري ودفن في السامرة، وخلفه ابنه أخآب على العرش.","16:29":"وملك أخآب بن عمري على إسرائيل في السنة الثامنة والثلاثين لحكم آسا ملك يهوذا، ودامت ولايته على إسرائيل في السامرة مدة اثنتين وعشرين سنة.","16:30":"وارتكب أخآب بن عمري الشر في عيني الرب، حتى فاق إثمه جميع أسلافه.","16:31":"وكأنما كان الانهماك في ارتكاب خطايا يربعام بن نباط أمرا تافها، فتزوج من إيزابل ابنة أثبعل ملك الصيدونيين، وغوى وراء البعل وسجد له.","16:32":"وشيد مذبحا للبعل في معبد البعل الذي بناه في السامرة.","16:33":"وأقام أخآب منحوتات الأصنام، وتفاقم شر أعماله ليثير غيظ الرب إله إسرائيل أكثر من سائر ملوك إسرائيل السابقين.","16:34":"وفي عهده بنى حيئيل البيتئيلي أريحا. وعندما أرسى أساسها مات ابنه الأكبر أبيرام، وعندما نصب بواباتها مات ابنه الأصغر سجوب، فتحقق بذلك وعيد الرب الذي نطق به على لسان يشوع بن نون.","17:1":"وقال إيليا التشبي من أهل جلعاد لأخآب: «حي هو الرب إله إسرائيل الذي أخدمه، إنه لن يهطل ندى ولا مطر في هذه السنين، إلا حين أعلن ذلك».","17:2":"وأمر الرب إيليا:","17:3":"«امض من هنا واتجه نحو المشرق، واختبىء عند نهر كريث المقابل لنهر الأردن،","17:4":"فتشرب من مياهه وتقتات مما تحضره لك الغربان التي أمرتها أن تعولك هناك».","17:5":"فانطلق ونفذ أمر الرب، وأقام عند نهر كريث مقابل نهر الأردن،","17:6":"فكانت الغربان تحضر إليه الخبز واللحم صباحا ومساء، وكان يشرب من ماء النهر.","17:7":"وما لبث أن جف النهر بعد زمن، لأنه لم يهطل مطر على الأرض.","17:8":"فخاطب الرب إيليا:","17:9":"«قم وتوجه إلى صرفة التابعة لصيدون، وامكث هناك، فقد أمرت هناك أرملة أن تتكفل بإعالتك».","17:10":"فذهب إلى صرفة. وعندما وصل إلى بوابة المدينة شاهد امرأة تجمع حطبا، فقال لها: «هاتي لي بعض الماء في إناء لأشرب».","17:11":"وفيما هي ذاهبة لتحضره ناداها ثانية وقال: «هاتي لي كسرة خبز معك».","17:12":"فأجابته: «حي هو الرب إلهك إنه ليس لدي كعكة، إنما حفنة دقيق في الجرة، وقليل من الزيت في قارورة. وها أنا أجمع بعض عيدان الحطب لآخذها وأعد لي ولابني طعاما نأكله ثم نموت».","17:13":"فقال لها إيليا: «لا تخافي. امضي واصنعي كما قلت، ولكن أعدي لي منه كعكة صغيرة أولا وأحضريها لي، ثم اعملي لك ولابنك أخيرا،","17:14":"لأن هذا ما يقوله الرب إله إسرائيل: إن جرة الدقيق لن تفرغ، وقارورة الزيت لن تنقص، إلى اليوم الذي يرسل فيه الرب مطرا على وجه الأرض».","17:15":"فراحت إلى منزلها ونفذت كلام إيليا، فتوافر لها طعام لتأكل هي وابنها وإيليا لمدة طويلة.","17:16":"جرة الدقيق لم تفرغ، وقارورة الزيت لم تنقص، تماما كما قال الرب على لسان إيليا.","17:17":"وحدث بعد زمن أن ابن المرأة صاحبة البيت اشتد عليه المرض، ومات،","17:18":"فقالت لإيليا: «أي ذنب جنيته بحقك يارجل الله؟ هل جئت إلي لتذكرني بإثمي وتميت ابني؟»","17:19":"فقال لها: «أعطيني ابنك». وأخذه منها وصعد به إلى العلية التي كان مقيما فيها وأضجعه على سريره،","17:20":"واستغاث بالرب متضرعا: «أيها الرب إلهي، أإلى الأرملة التي أنا نازل عندها تسيء أيضا وتميت ابنها؟»","17:21":"ثم تمدد إيليا على جثة الولد ثلاث مرات وابتهل إلى الرب: «يارب إلهي، أرجع نفس هذا الولد إليه».","17:22":"فاستجاب الرب دعاء إيليا، ورجعت نفس الولد إليه فعاش.","17:23":"فأخذ إيليا الولد ونزل به من العلية إلى البيت، وسلمه إلى أمه، وقال لها: «انظري، إن ابنك حي»","17:24":"فقالت المرأة لإيليا: «الآن علمت أنك رجل الله، وأن الله ينطق على لسانك بالحق».","18:1":"وبعد ثلاث سنوات قال الرب لإيليا: «اذهب وامثل أمام أخآب، وقل له إنني سأسكب مطرا على الأرض».","18:2":"فمضى إيليا ليبلغ أخآب الرسالة، وكانت المجاعة الشديدة قد عمت السامرة.","18:3":"فاستدعى أخآب عوبديا مدير شؤون القصر، وكان عوبديا يتقي الرب جدا.","18:4":"فحين شرعت إيزابل في قتل أنبياء الرب، أخذ عوبديا مئة نبي وخبأهم خمسين خمسين في مغارتين، وتكفل بإعالتهم بالطعام والماء.","18:5":"وكان أخآب قد قال لعوبديا: «طف في البلاد وابحث عن جميع عيون الماء وفي الأودية، لعلنا نجد عشبا فنحيي الخيل والبغال، فلا تهلك كل البهائم».","18:6":"فقسما البلاد بينهما ليطوفا بها، فذهب أخآب في طريق وحده، وذهب عوبديا في طريق آخر وحده.","18:7":"وفيما كان عوبديا في الطريق التقاه إيليا، فعرفه، فارتمى على وجهه قائلا: «هل أنت هو سيدي إيليا؟»","18:8":"فأجابه: «أنا هو، فاذهب وقل لسيدك إني هنا».","18:9":"فقال: «أية خطيئة ارتكبت حتى تسلم عبدك ليد أخآب ليميتني؟","18:10":"حي هو الرب إلهك إنه لم تبق أمة ولا مملكة لم يرسل إليها سيدي من يبحث عنك، فكانوا يقولون: إننا لم نعثر عليه، فكان أخآب يستحلف المملكة والأمة لتقسم أنها حقا لم تجدك.","18:11":"والآن تطلب إلي أن أذهب وأقول للملك إنك هنا،","18:12":"وما إن أنطلق من عندك لأخبره حتى يحملك روح الرب إلى حيث لا أدري، فيأتي أخآب ولا يجدك فيقتلني، وأنا عبدك أتقي الرب منذ صباي.","18:13":"ألم يطلع سيدي عما فعلته حين شرعت إيزابل تقتل أنبياء الرب، كيف خبأت مئة رجل، خمسين خمسين في مغارتين، وتكفلت بإعالتهم بالطعام والماء؟","18:14":"وأنت الآن تطالبني أن أذهب وأقول للملك إنك هنا، فيقتلني!»","18:15":"فقال إيليا: «حي هو الرب القدير الذي أنا واقف أمامه، إنني اليوم أحضر لمواجهة أخآب».","18:16":"فانطلق عوبديا للقاء أخآب وأخبره، فجاء أخآب للقاء إيليا.","18:17":"وما إن رأى أخآب إيليا حتى قال له: «أهذا أنت يامكدر إسرائيل؟»","18:18":"فأجابه إيليا: «أنا لست مكدر إسرائيل، بل أنت وبيت أبيك، بعصيانكم وصايا الرب وضلالكم وراء البعليم.","18:19":"فالآن أرسل واستدع لي كل بني إسرائيل إلى جبل الكرمل، وكذلك أنبياء البعل الأربع مئة والخمسين، وأنبياء عشتاروث الأربع مئة الآكلين على مائدة إيزابل».","18:20":"فاستدعى أخآب جميع بني إسرائيل، وجمع الأنبياء إلى جبل الكرمل،","18:21":"فخاطب إيليا الشعب: «حتى متى تظلون تعرجون بين الفرقتين؟ إن كان الرب هو الله فاتبعوه، وإن كان البعل هو الله فاتبعوه». فلم يجبه الشعب بكلمة.","18:22":"ثم قال إيليا للشعب: «أنا بقيت وحدي نبيا للرب، وأنبياء البعل أربع مئة وخمسون.","18:23":"فأعطونا ثورين، وليختر أنبياء البعل أحدهما، ويقطعوه ويضعوه على الحطب من غير أن يشعلوا نارا، وأنا أقرب الثور الآخر وأضعه على الحطب من غير أن أشعل نارا.","18:24":"ثم تتضرعون باسم آلهتكم، وأنا أدعو باسم الرب إلهي. والإله الذي يستجيب وينزل نارا يكون هو الله الحق». فأجاب جميع بني إسرائيل: «هذا قول صائب».","18:25":"فقال إيليا عندئذ لأنبياء البعل: «اختاروا لأنفسكم ثورا واحدا، وقربوا أولا لأنكم الأكثر عددا وادعوا باسم آلهتكم، ولكن إياكم أن تشعلوا نارا».","18:26":"فأحضروا الثور الذي أعطي لهم ووضعوه على المذبح، وظلوا يدعون باسم البعل من الصباح إلى الظهر قائلين: «يابعل استجب لنا». فلم يكن هناك صوت أو مجيب. فراحوا يرقصون حول المذبح المشيد.","18:27":"وعند الظهر سخر بهم إيليا وقال: «ادعوا بصوت أعلى فهو حقا إله! لعله مستغرق في التأمل أو في خلوة أو في سفر! أو لعله نائم فيستيقظ».","18:28":"فشرعوا يهتفون بصوت أعلى، ويمزقون أجسادهم بالسيوف والرماح كعادتهم، حتى سال منهم الدم.","18:29":"وانقضت ساعات الظهر، وظلوا يهذون صارخين حتى حل وقت إصعاد التقدمة المسائية، من غير أن يكون هناك صوت أو مجيب.","18:30":"عندئذ قال إيليا للشعب كله: «تقدموا إلي». فدنا جميع الشعب منه، فرمم مذبح الرب المنهدم،","18:31":"ثم أخذ اثني عشر حجرا حسب عدد أسباط إسرائيل، ذرية يعقوب الذي دعاه الله إسرائيل","18:32":"وبنى بهذه الحجارة مذبحا باسم الرب، وحفر حوله قناة تسع نحو كيلتين من الحب.","18:33":"ثم رتب الحطب وقطع الثور، ووضع أجزاءه على الحطب وأمر أن يملأوا أربع جرات ماء ويصبوها على المحرقة وعلى الحطب.","18:34":"ثم قال «ثنوا، فثنوا، وعاد يأمر: «ثلثوا»، فثلثوا.","18:35":"حتى جرى الماء حول المذبح وامتلأت القناة أيضا بالماء.","18:36":"وفي ميعاد ذبيحة المساء صلى إيليا: «أيها الرب إله إبراهيم وإسحق وإسرائيل، ليعلم اليوم أنك أنت الله في إسرائيل، وأني أنا عبدك، وبأمرك قد أقدمت على هذه الأمور.","18:37":"استجبني يارب، استجبني، ليدرك هذا الشعب أنك أنت الرب الإله، وأنك أنت ترد قلوبهم إليك».","18:38":"فنزلت نار من السماء التهمت المحرقة والحطب والحجارة والتراب ولحست ماء القناة.","18:39":"فلما شاهد جميع بني إسرائيل ذلك خروا ساجدين على وجوههم إلى الأرض هاتفين: «الرب هو الله ! الرب هو الله !»","18:40":"فقال إيليا: «اقبضوا على أنبياء البعل ولا تدعوا رجلا منهم يفلت» فقبضوا عليهم، فساقهم إيليا إلى نهر قيشون وذبحهم هناك.","18:41":"وقال إيليا لأخآب: «اصعد كل واشرب لأنني أسمع صوت دوي مطر».","18:42":"فمضى أخآب ليأكل ويشرب، وأما إيليا فارتقى إلى قمة جبل الكرمل وجلس على الأرض وخبأ رأسه بين ركبتيه.","18:43":"وقال لغلامه: «اذهب وتطلع نحو البحر». فمضى الغلام وتطلع نحو البحر وقال: «لا أرى شيئا». فأمر إيليا: «اذهب وتطلع، سبع مرات»","18:44":"وفي المرة السابعة قال الغلام: «أرى غيمة صغيرة في حجم كف إنسان صاعدة من البحر». فقال إيليا: «انطلق وقل لأخآب أعد مركبتك وانزل من الجبل لئلا يعيقك المطر عن السفر».","18:45":"وسرعان ما تلبدت السماء بالغيوم، وهبت ريح عاصفة، وهطل مطر غزير، فاندفع أخآب بمركبته نحو يزرعيل.","18:46":"وحلت قوة الرب في إيليا، فلف عباءته حول حقويه وركض ليسبق أخآب إلى مدخل يزرعيل.","19:1":"وأخبر أخآب إيزابل بما صنعه إيليا، وكيف قتل جميع أنبياء البعل بالسيف،","19:2":"فبعثت إيزابل رسولا إلى إيليا قائلة: «لتعاقبني الآلهة أشد عقاب وتزد، إن لم أقتلك في مثل هذا الوقت غدا، فتكون كمثل الذين قتلتهم».","19:3":"فلما سمع إيليا ذلك هرب لينجو بنفسه، ووصل إلى بئر سبع التابعة ليهوذا، حيث ترك خادمه.","19:4":"ثم هام وحده في الصحراء مسيرة يوم، حتى أتى شجرة شيح، فجلس تحتها، وتمنى الموت لنفسه وقال: «قد كفى الآن ياربي، خذ نفسي فلست خيرا من آبائي».","19:5":"واضطجع ونام تحت شجرة الشيح، وإذا بملاك يمسه ويقول: «قم وكل».","19:6":"فتطلع حوله وإذا به يرى عند رأسه رغيفا مخبوزا على الجمر وجرة ماء. فأكل وشرب، ثم عاد ونام.","19:7":"ومسه ملاك الرب ثانية قائلا: «قم وكل، لأن أمامك مسافة طويلة للسفر».","19:8":"فقام وأكل وشرب، ومشى بقوة تلك الوجبة أربعين نهارا وأربعين ليلة، حتى بلغ جبل الله حوريب.","19:9":"فدخل مغارة هناك وبات فيها وقال الرب لإيليا: «ماذا تفعل هنا ياإيليا؟»","19:10":"فأجاب: «غرت غيرة للرب الإله القدير، لأن بني إسرائيل تنكروا لعهدك وهدموا مذابحك وقتلوا أنبياءك بالسيف، وبقيت وحدي. وها هم يبغون قتلي أيضا»","19:11":"فقال له: «اخرج وقف على الجبل أمامي، لأني مزمع أن أعبر». ثم هبت ريح عاتية شقت الجبال وحطمت الصخور، ولكن الرب لم يكن في الريح. ثم حدثت زلزلة، ولم يكن الرب في الزلزلة.","19:12":"وبعد الزلزلة اجتازت به نار، ولم يكن الرب في النار. وبعد النار رف في مسامع إيليا صوت منخفض هامس.","19:13":"فلما سمع إيليا الصوت، لف وجهه بردائه، وخرج ووقف في باب الكهف. وإذا بصوت يخاطبه: «ماذا تفعل هنا ياإيليا؟»","19:14":"فأجاب: «غرت غيرة للرب الإله القدير، لأن بني إسرائيل تنكروا لعهدك وهدموا مذابحك وقتلوا أنبياءك بالسيف، وبقيت وحدي، وها هم يبغون قتلي».","19:15":"فقال له الرب: «اذهب راجعا في الطريق الصحراوية المفضية إلى دمشق، وهناك امسح حزائيل ملكا على أرام،","19:16":"ثم امسح ياهو بن نمشي ملكا على إسرائيل، وكذلك امسح أليشع بن شافاط من آبل محولة نبيا خلفا لك.","19:17":"فالذي ينجو من سيف حزائيل يقتله ياهو، والذي ينجو من سيف ياهو يقتله أليشع.","19:18":"ولقد أبقيت في إسرائيل سبعة آلاف لم يحنوا ركبهم للبعل ولم تقبله أفواههم».","19:19":"فانطلق إيليا من هناك فوجد أليشع بن شافاط يحرث حقلا، وأمامه أحد عشر زوجا من البقر، وهو يسير خلف الزوج الثاني عشر. فمر به إيليا وطرح عليه رداءه،","19:20":"فترك البقر وركض وراء إيليا وقال: «دعني أودع أبي وأمي وأتبعك». فقال له: «ارجع، فأي شيء فعلته لك؟»","19:21":"فرجع أليشع وأخذ زوج بقر ذبحهما وسلق لحمهما على خشب المحراث ووزعه على الشعب فأكلوا، ثم قام ولحق بإيليا وواظب على خدمته.","20:1":"وحشد بنهدد ملك أرام كل جيشه، بعد أن انضم إليه اثنان وثلاثون ملكا بخيلهم ومركباتهم، وحاصر السامرة عاصمة إسرائيل.","20:2":"ثم بعث بنهدد رسالة إلى أخآب ملك إسرائيل في السامرة تقول:","20:3":"«لي كل فضتك وذهبك وأجمل نسائك وبنوك الحسان».","20:4":"فأجاب ملك إسرائيل: «لك ما طلبته ياسيدي الملك، فأنا وكل ما أملكه لك».","20:5":"فبعث بنهدد رسالة أخرى إلى أخآب تقول: «كنت قد أرسلت إليك طالبا أن تقدم لي كل فضتك وذهبك وأجمل نسائك وبنيك الحسان،","20:6":"ولكني أيضا في نحو هذا الوقت غدا أرسل رجالي إليك ليفتشوا قصرك وبيوت عبيدك، ليستولوا على كل ما هو نفيس».","20:7":"فاستدعى ملك إسرائيل جميع زعماء البلاد وقال: «اعلموا وانظروا أن بنهدد يبغي الشر، فقد بعث يطلب إلي تسليم نسائي وبني وفضتي وذهبي، فوافقت».","20:8":"فقال له كل زعماء البلاد وسائر الشعب: «لا تسمع له ولا تخضع لطلبه».","20:9":"فقال أخآب لرسل بنهدد: «قولوا لسيدي الملك إنني مستعد أن أنفذ جميع مطالبه الأولى، أما المطالب الثانية فلا أستطيع تلبيتها». فرجع الرسل بجوابه إلى بنهدد.","20:10":"فبعث إليه بنهدد قائلا: «لتعاقبني الآلهة أشد عقاب وتزد، إن بقي من تراب السامرة ما يكفي لملء قبضة كل واحد من رجالي».","20:11":"فأجاب ملك إسرائيل: «قولوا له: لا يفتخر من يشد درعه كمن يحله» (أي الفخر يكون بعد المعركة لا قبلها).","20:12":"فلما سمع بنهدد هذا الكلام وهو يشرب الخمر في الخيام مع حلفائه الملوك، أمر رجاله أن يتأهبوا للقتال، فاستعدوا للهجوم على المدينة.","20:13":"وإذا بنبي يتقدم إلى أخآب قائلا: «هذا ما يقوله الرب: هل ترى هذا الجيش الغفير؟ ها أنا أنصرك عليه اليوم، فتعلم أني أنا الرب».","20:14":"فسأل أخآب: «بمن يكون النصر؟» فأجاب: «هذا ما يقوله الرب: بقوات رؤساء المقاطعات» فعاد يسأل: «من يبتديء الحرب؟» فأجاب: «أنت».","20:15":"فأحصى أخآب رجال رؤساء المقاطعات، فبلغوا مئتين واثنين وثلاثين. ثم أحصى بعدهم بقية جيش إسرائيل فكانوا سبعة آلاف.","20:16":"واندفعوا عند الظهر من المدينة وبنهدد منهمك في السكر في الخيام مع حلفائه الملوك الاثنين والثلاثين،","20:17":"وتقدمت قوات رؤساء المقاطعات أولا، فقال المراقبون لبنهدد: «رجال من السامرة قادمون علينا»","20:18":"فقال: «اقبضوا عليهم أحياء، سواء كان قدومهم للهدنة أو للحرب».","20:19":"وهكذا اندفعت قوات رؤساء المقاطعات من المدينة، وفي أعقابها تقدم الجيش الإسرائيلي","20:20":"وهاجم كل رجل منهم واحدا من جيش الأراميين، فهرب الأراميون، ولاحقهم الإسرائيليون. وتمكن بنهدد ملك أرام مع بعض فرسانه من النجاة على خيولهم.","20:21":"وتقدم ملك إسرائيل واقتحم الخيل والمركبات، وأنزل بالأراميين هزيمة فادحة.","20:22":"واقترب النبي من أخآب وقال له: «اذهب وتأهب، ودبر شؤونك، وفكر بما تفعل، لأنه في نهاية هذا العام يهاجمك ملك أرام،","20:23":"لأن رجاله قد قالوا له: إن آلهة الإسرائيليين آلهة جبال، لذلك انتصروا هذه المرة، ولكن إن حاربناهم في السهل فإننا نهزمهم.","20:24":"كما اقترحوا عليه عزل الملوك من قيادة الجيوش، وتعيين ضباط بدلا منهم.","20:25":"وقالوا لبنهدد: جهز لنفسك جيشا ضخما، يكون عدده كعدد الجيش الذي فقدته، فرسا بفرس ومركبة بمركبة، فنحاربهم في السهل ونقهرهم».فعمل بنهدد باقتراحهم ورأيهم.","20:26":"وفي نهاية العام جهز بنهدد جيشا من الأراميين، وانطلق إلى أفيق ليحارب الإسرائيليين.","20:27":"وحشدت إسرائيل جيشها وجهزت مؤونته وتقدموا للقائهم، فكانوا بالمقارنة بالأراميين الذين ملأوا الأرض نظير قطيعين من المعزى.","20:28":"فجاء رجل الله إلى أخآب وقال: «هذا ما يقوله الرب: لأن الأراميين قد ادعوا أن الرب إنما هو إله جبال وليس هو إله أودية، فإنني سأنصرك على كل هذا الجيش الغفير، فتعلمون أني أنا الرب».","20:29":"وهكذا تواجه الطرفان سبعة أيام. وفي اليوم السابع دارت رحى الحرب، فقتل بنو إسرائيل في يوم واحد مئة ألف من مشاة أرام،","20:30":"وهرب الأحياء إلى داخل مدينة أفيق، فانهار السور على السبعة والعشرين ألف رجل الباقين. أما بنهدد فقد لجأ إلى المدينة واختبأ فيها في مخدع داخل مخدع.","20:31":"فقال له رجاله: «لقد سمعنا أن ملوك إسرائيل ملوك حليمون، فلنرتد مسوحا حول أحقائنا، ونضع حبالا على رؤوسنا، ونخرج إلى ملك إسرائيل، لعله يعفو عنك».","20:32":"فارتدوا مسوحا حول أحقائهم، ووضعوا حبالا على رؤوسهم، ومثلوا أمام ملك إسرائيل قائلين: «عبدك بنهدد يرجو العفو عن حياته». فقال: «ألا يزال حيا؟ هو أخي!»","20:33":"فتفاءل رجال بنهدد، وتشبثوا بالأمل، وقالوا: «نعم هو أخوك». فقال لهم أخآب: «اذهبوا وأحضروه.» وعندما وصل، أصعده معه في مركبته،","20:34":"فقال بنهدد: «إني أرد المدن التي استولى عليها أبي من أبيك، وتقيم لنفسك أسواقا تجارية في دمشق مماثلة للأسواق التي أقامها أبي في السامرة». فأجابه الملك: «وبناء على هذا العهد فإنني أطلقك حرا». فقطع له بنهدد عهدا وأطلقه أخآب.","20:35":"ونزولا عند أمر الرب، قال رجل من بني الأنبياء لصاحبه: «اضربني بسيفك». فأبى الرجل أن يضربه.","20:36":"فقال له: «إنك لم تطع أمر الرب، فعند انصرافك من عندي يقتلك أسد». وحين خرج من عنده لقيه أسد وصرعه.","20:37":"ثم صادف النبي رجلا آخر، فقال له: «اضربني». فضربه وجرحه،","20:38":"فمضى النبي واعترض طريق الملك متنكرا بعصابة على عينيه.","20:39":"وعندما اجتاز أخآب أمامه ناداه وقال: «خرج عبدك في أثناء اشتداد المعركة، وإذا برجل أقبل إلي بأسير، وقال: احرس هذا الرجل، وإن فقد تكون نفسك عوض نفسه، أو تدفع وزنة من الفضة (نحو ستة وثلاثين كيلوجراما)","20:40":"وفيما عبدك منهمك في بعض الأمور، اختفى الأسير». فقال له ملك إسرائيل: «لقد حكمت على نفسك بما قضيت به».","20:41":"عندئذ بادر النبي فرفع العصابة عن عينيه فأدرك الملك أنه من بني الأنبياء.","20:42":"وقال للملك: «هذا ما يقوله الرب: لأنك أبقيت على حياة رجل قضيت بهلاكه، فستموت بدلا منه، ويهلك شعبك بدلا من شعبه».","20:43":"فانصرف ملك إسرائيل إلى قصره في السامرة مكتئبا مغموما.","21:1":"وحدث أنه كان لنابوت اليزرعيلي كرم في يزرعيل، مجاور لقصر أخآب ملك السامرة،","21:2":"فقال أخآب لنابوت: «قايضني كرمك لأجعله حديقة خضروات، لأنه مجاور لقصري، فأعطيك بدلا منه كرما أفضل منه، أو إذا راق لك أدفع ثمنه فضة».","21:3":"فأجاب نابوت: «معاذ الله أن أفرط في ميراث آبائي».","21:4":"فدخل أخآب قصره مكتئبا مهموما متأثرا من قول نابوت اليزرعيلي: «لا أفرط في ميراث آبائي». واستلقى فوق سريره مشيحا بوجهه نحو الحائط عازفا عن الطعام.","21:5":"فأقبلت إليه زوجته إيزابل قائلة: «مالي أراك منقبضا عازفا عن الطعام؟»","21:6":"فأجابها: «لأني قلت لنابوت اليزرعيلي: بعني كرمك، وإذا شئت قايضتك بكرم آخر، فأجاب: لا أعطيك كرمي»","21:7":"فقالت له إيزابل: «أهكذا تحكم كملك على إسرائيل؟ قم وتناول طعاما وطب نفسا، فأنا أحصل لك على كرم نابوت اليزرعيلي».","21:8":"ثم حررت رسائل باسم أخآب، وختمتها بخاتمه وبعثت بها إلى شيوخ ووجهاء يزرعيل حيث يقيم نابوت.","21:9":"وقالت فيها: «ادعوا الشعب للصوم، وأجلسوا نابوت في مكان الصدارة،","21:10":"وأقيموا شاهدي زور ليشهدا أن نابوت جدف على الله وعلى الملك، ثم أخرجوه من المدينة وارجموه حتى يموت».","21:11":"فنفذ شيوخ مدينته ووجهاؤها أوامر إيزابل كما هي واردة في الرسائل التي بعثت بها إليهم.","21:12":"فتداعوا للصوم، وأجلسوا نابوت في مكان الصدارة.","21:13":"ثم أقبل شاهدا زور وجلسا تجاهه، وشهدا على نابوت أمام الشعب قائلين: «قد جدف نابوت على الله وعلى الملك». فجروه إلى خارج المدينة ورجموه بالحجارة حتى مات.","21:14":"وأبلغوا إيزابل أن نابوت قد رجم فمات.","21:15":"فلما سمعت إيزابل بموت نابوت قالت لأخآب: «قم ورث كرم نابوت اليزرعيلي، الذي أبى أن يبيعك إياه بفضة، لأن نابوت قد أصبح في عداد الأموات».","21:16":"عندئذ قام أخآب ونزل ليتفقد كرم نابوت ويستولي عليه.","21:17":"ولكن الرب قال لإيليا التشبي:","21:18":"«قم امض للقاء أخآب ملك إسرائيل المقيم في السامرة، فها هو قد نزل إلى كرم نابوت ليستولي عليه،","21:19":"وقل له: هذا ما يقوله الرب: هل قتلت وامتلكت أيضا؟ في المكان الذي لعقت فيه الكلاب دم نابوت تلعق الكلاب دمك أيضا».","21:20":"وما إن رأى أخآب إيليا حتى قال: «هل وجدتني ياعدوي؟» فأجابه: «قد وجدتك لأنك بعت نفسك لارتكاب الشر في عيني الرب.","21:21":"لهذا يقول الرب: ها أنا أجلب عليك شرا وأبيد ذريتك وأفني كل ذكر لك، حرا كان أم عبدا.","21:22":"وأجعل مصير بيتك كمصير بيت يربعام بن نباط، وكمصير بيت بعشا بن أخيا، لفرط ما أثرته من غيظي، ولأ نك استغويت إسرائيل لارتكاب المعصية».","21:23":"وأصدر الرب قضاءه على إيزابل قائلا: «إن الكلاب ستلتهم جثتها عند مترسة يزرعيل.","21:24":"وكل من يموت من أسرتك في المدينة تأكله الكلاب ومن يموت منهم في الحقل تنهشه الطيور».","21:25":"ولم يكن نظير أخآب الذي أغوته زوجته إيزابل، فباع نفسه لارتكاب الشر في عيني الرب.","21:26":"فقد غرق في حمأة الرجاسة بعبادته الأصنام، مثلما فعل الأموريون الذين طردهم الرب من أمام بني إسرائيل.","21:27":"وعندما سمع أخآب هذا القضاء، مزق ثيابه وارتدى مسحا، وصام واضطجع بثياب المسح ومشى ذليلا.","21:28":"فقال الرب لإيليا:","21:29":"«هل رأيت كيف ذل أخآب أمامي؟ من أجل ذلك لن أجلب الشر عليه في حياته، بل أنزل العقاب ببيته في أيام ابنه».","22:1":"وانقضت ثلاث سنوات من غير أن تنشب حرب بين أرام وإسرائيل.","22:2":"وفي السنة الثالثة قدم يهوشافاط ملك يهوذا لزيارة ملك إسرائيل،","22:3":"فقال ملك إسرائيل لرجاله: «أتدرون أن راموت جلعاد هي لنا، ومع ذلك لم نفعل شيئا لاسترجاعها من أرام؟»","22:4":"وسأل أخآب يهوشافاط: «هل تشترك معي في الحرب لاسترجاع راموت جلعاد؟» فأجابه يهوشافاط: «مثلي مثلك: شعبي كشعبك وخيلي كخيلك».","22:5":"ثم قال يهوشافاط لملك إسرائيل: «اطلب اليوم مشورة الرب».","22:6":"فجمع ملك إسرائيل نحو أربع مئة من أنبياء الأصنام وسألهم: «هل أذهب للحرب إلى راموت جلعاد أم أمتنع؟» فأجابوه: «اذهب، فإن الرب سينصرك ويسلمها لك».","22:7":"فقال يهوشافاط: «ألا يوجد هنا بعد نبي من أنبياء الرب فنسأله المشورة؟»","22:8":"فأجاب ملك إسرائيل: «يوجد بعد رجل واحد، يمكننا عن طريقه أن نطلب مشورة الرب، ولكني أمقته لأنه لا يتنبأ علي بغير الشر. إنه ميخا بن يملة». فقال يهوشافاط: «لا تقل هذا أيها الملك».","22:9":"فأمر أخآب أحد رجاله باستدعاء ميخا بن يملة.","22:10":"وكان كل من ملك إسرائيل ويهوشافاط ملك يهوذا يجلس على عرش في ساحة عند مدخل باب السامرة، وقد ارتديا حللهما الملكية، والأنبياء جميعهم يتنبأون أمامهما.","22:11":"وصنع صدقيا بن كنعنة لنفسه قرني حديد وقال: «هكذا يقول الرب: بهذه تنطح الأراميين حتى يهلكوا».","22:12":"وتنبأ جميع الأنبياء بمثل هذا الكلام قائلين: «اذهب إلى راموت جلعاد فتظفر بها، لأن الرب يسلمها إلى الملك».","22:13":"وقال الرسول الذي انطلق لاستدعاء ميخا: «لقد تنبأ جميع الأنبياء بفم واحد مبشرين الملك بالخير، فليكن كلامك موافقا لكلامهم يحمل بشائر الخير».","22:14":"فأجاب ميخا: «حي هو الرب إنني لن أنطق إلا بما يقوله الرب».","22:15":"ولما حضر أمام الملك سأله: «ياميخا، هل نذهب للحرب إلى راموت جلعاد، أم نمتنع؟» فأجابه (بتهكم): «اذهب فتظفر بها لأن الرب يسلمها إلى الملك».","22:16":"فقال له الملك: «كم مرة استحلفتك باسم الرب ألا تخبرني إلا الحق».","22:17":"عندئذ قال ميخا: «رأيت كل إسرائيل مبددين على الجبال كخراف بلا راع. فقال الرب: ليس لهؤلاء قائد، فليرجع كل واحد منهم إلى بيته بسلام».","22:18":"فقال ملك إسرائيل ليهوشافاط: «ألم أقل لك إنه لا يتنبأ علي بغير الشر؟»","22:19":"فأجاب ميخا: «إذا فاسمع كلام الرب: قد شاهدت الرب جالسا على كرسيه وكل أجناد السماء ماثلة عن يمينه وعن يساره.","22:20":"فسأل الرب: من يغري أخآب ليخرج للحرب ويموت في راموت جلعاد؟ فأجاب كل منهم بشيء.","22:21":"ثم تقدم روح الضلال وقال: أنا أغويه. فسأله الرب: بماذا؟","22:22":"فأجاب: أخرج، وأصبح روح ضلال في أفواه جميع أنبيائه. فقال الرب: إنك قادر على إغوائه وتفلح في ذلك، فامض ونفذ هذا الأمر.","22:23":"وها الرب قد جعل الآن روح ضلال في أفواه جميع أنبيائك هؤلاء، وقد قضى عليك بالشر».","22:24":"فاقترب صدقيا بن كنعنة من ميخا وضربه على الفك قائلا: «من أين عبر روح الرب مني ليكلمك؟»","22:25":"فأجابه ميخا: «ستعرف ذلك في اليوم الذي تلجأ فيه للاختباء من مخدع إلى مخدع».","22:26":"حينئذ أمر ملك إسرائيل قائلا: «اقبضوا على ميخا وسلموه إلى آمون رئيس المدينة وإلى يوآش ابن الملك،","22:27":"وقولوا لهما: إن الملك أمر بإيداع هذا في السجن، وأطعموه خبز الضيق وماء الضيق حتى أرجع من الحرب بسلام».","22:28":"فأجابه ميخا: «إن رجعت بسلام لا يكون الرب قد تكلم على لساني، فاشهدوا على ذلك أيها الشعب جميعا».","22:29":"وتوجه ملك إسرائيل ويهوشافاط ملك يهوذا إلى راموت جلعاد.","22:30":"فقال أخآب ليهوشافاط: «إنني سأخوض الحرب متنكرا، أما أنت فارتد ثيابك الملكية». وهكذا تنكر ملك إسرائيل وخاض الحرب.","22:31":"وقال ملك أرام لقادة مركباته الاثنين والثلاثين: «لا تحاربوا صغيرا ولا كبيرا إلا ملك إسرائيل وحده».","22:32":"فلما شاهد قادة المركبات يهوشافاط، ظنوا أنه ملك إسرائيل، فحاصروه ليقاتلوه، فأطلق يهوشافاط صرخة،","22:33":"أدركوا منها أنه ليس ملك إسرائيل، فارتدوا عنه.","22:34":"ولكن حدث أن جنديا أطلق سهمه من قوسه غير متعمد، فأصاب ملك إسرائيل بين أوصال درعه، فقال أخآب لقائد مركبته: «استدر وأخرجني من أرض المعركة فقد جرحت»","22:35":"واشتدت المعركة في ذلك اليوم، وأوقف الملك مركبته في مواجهة الأراميين، ولم يلبث أن مات عند المساء، فجرى دم الجرح إلى أرض المركبة.","22:36":"وعند غروب الشمس تجاوبت صرخة بين قوات الجيش: «ليرجع كل رجل إلى مدينته وإلى أرضه».","22:37":"وهكذا مات الملك فنقلوه إلى السامرة حيث دفن فيها.","22:38":"وعندما غسلت مركبته وأسلحته في بركة السامرة، جاءت الكلاب ولحست دمه. فتحقق بذلك كل ما أنذر به الرب.","22:39":"أما بقية أخبار أخآب وإنجازاته وبيت العاج الذي بناه، وكل المدن التي عمرها، أليست هي مدونة في تاريخ أخبار أيام ملوك إسرائيل؟","22:40":"ودفن أخآب مع آبائه وخلفه ابنه أخزيا على الملك.","22:41":"وملك يهوشافاط بن آسا على يهوذا في السنة الرابعة من حكم أخآب ملك إسرائيل.","22:42":"وكان يهوشافاط في الخامسة والثلاثين حين ملك، ودام حكمه خمسا وعشرين سنة في أورشليم، واسم أمه عزوبة بنت شلحي","22:43":"واقتفى خطى أبيه آسا، ولم يحد عنها صانعا ما هو صالح في عيني الرب. إلا أن مذابح المرتفعات لم تهدم، بل كان الشعب لا يزال يذبح ويوقد عليها.","22:44":"ووقع يهوشافاط معاهدة صلح مع ملك إسرائيل.","22:45":"أما بقية أخبار يهوشافاط وما أبداه من بأس، وكيف حارب، أليست هي مدونة في كتاب تاريخ أخبار أيام ملوك يهوذا؟","22:46":"كما أباد من البلاد الذين يمارسون الشذوذ الجنسي في عبادتهم الوثنية ممن بقوا من أيام أبيه آسا.","22:47":"ولم يكن في زمانه ملك على أدوم، بل تولى الحكم وكيل للملك.","22:48":"وبنى يهوشافاط أسطولا تجاريا لكي يبحر إلى أوفير ويعود محملا بالذهب، ولكن السفن لم تبحر لأنها تحطمت في عصيون جابر.","22:49":"حينئذ قال أخزيا بن أخآب ليهوشافاط: «ليبحر رجالي مع رجالك في السفن». فأبى يهوشافاط.","22:50":"ومات يهوشافاط فدفن مع أسلافه في مدينة داود أبيه، وخلفه ابنه يهورام على العرش.","22:51":"وملك أخزيا بن أخآب على إسرائيل في السامرة، في السنة السابعة عشرة لحكم يهوشافاط ملك يهوذا، ودام ملكه سنتين،","22:52":"ارتكب فيهما الشر في عيني الرب، وسلك في سبل أبيه وأمه، وفي طريق يربعام بن نباط الذي استغوى إسرائيل لاقتراف الإثم،","22:53":"وعبد أخزيا البعل وسجد له، فأثار بذلك غيظ الرب، تماما كما فعل أبوه."};
